const TRACE_CHANGE_FLAG = 'layer.changeFlag';
const TRACE_INITIALIZE = 'layer.initialize';
const TRACE_UPDATE = 'layer.update';
const TRACE_FINALIZE = 'layer.finalize';
const TRACE_MATCHED = 'layer.matched';

const MAX_PICKING_COLOR_CACHE_SIZE = 2 ** 24 - 1;

const EMPTY_ARRAY = Object.freeze([]);

// Only compare the same two viewports once
const areViewportsEqual = memoize(
  ({oldViewport, viewport}: {oldViewport: Viewport; viewport: Viewport}): boolean => {
    return oldViewport.equals(viewport);
  }
);

let pickingColorCache = new Uint8ClampedArray(0);

function getPickingAttribute(attributes: Record<string, Attribute>): Attribute | undefined {
  return attributes.rowIndexes || attributes.pickingColors || attributes.instancePickingColors;
}

function getPickingIndexAttribute(attributes: Record<string, Attribute>): Attribute | undefined {
  return attributes.rowIndexes;
}

function getPickingColorAttribute(attributes: Record<string, Attribute>): Attribute | undefined {
  return attributes.pickingColors || attributes.instancePickingColors;
}

/** Built-in highlight color, expressed in bytes. */
const DEFAULT_HIGHLIGHT_COLOR = [0, 0, 128, 128];

const defaultProps: DefaultProps<LayerProps> = {
  // data: Special handling for null, see below
  data: {type: 'data', value: EMPTY_ARRAY, async: true},
  dataComparator: {type: 'function', value: null, optional: true},
  _dataDiff: {
    type: 'function',
    // @ts-ignore __diff is not defined on data
    value: data => data && data.__diff,
    optional: true
  },
  query: null,
  sqlFunctions: {type: 'array', value: [], compare: true},
  dataTransform: {type: 'function', value: null, optional: true},
  _dataLoadOptions: 'auto',
  onDataProgress: {type: 'function', value: null, optional: true},
  onDataLoad: {type: 'function', value: null, optional: true},
  onError: {type: 'function', value: null, optional: true},
  fetch: {
    type: 'function',
    value: <LayerT extends Layer>(
      url: string,
      {
        propName,
        layer,
        loaders,
        loadOptions,
        signal
      }: {
        propName: string;
        layer: LayerT;
        loaders?: Loader[];
        loadOptions?: any;
        signal?: AbortSignal;
      }
    ) => {
      const {resourceManager} = layer.context;
      loadOptions = loadOptions || layer.getLoadOptions();
      loaders = loaders || layer.props.loaders;
      if (signal) {
        loadOptions = {
          ...loadOptions,
          core: {
            ...loadOptions?.core,
            fetch: {
              ...loadOptions?.core?.fetch,
              signal
            }
          }
        };
      }

      if (propName === 'data' && layer.props._dataLoadOptions !== 'auto') {
        resourceManager.unsubscribe({consumerId: layer.id, requestId: propName});
        return loadInBatches(url, loaders, loadOptions);
      }

      let inResourceManager = resourceManager.contains(url);

      if (!inResourceManager && !loadOptions) {
        // If there is no layer-specific load options, then attempt to cache this resource in the data manager
        resourceManager.add({resourceId: url, data: load(url, loaders), persistent: false});
        inResourceManager = true;
      }
      if (inResourceManager) {
        return resourceManager.subscribe({
          resourceId: url,
          onChange: data => layer.internalState?.reloadAsyncProp(propName, data),
          consumerId: layer.id,
          requestId: propName
        });
      }

      return load(url, loaders, loadOptions);
    }
  },
  updateTriggers: {}, // Update triggers: a core change detection mechanism in deck.gl

  visible: true,
  pickable: false,
  opacity: {type: 'number', min: 0, max: 1, value: 1},
  operation: 'draw',

  onHover: {type: 'function', value: null, optional: true},
  onClick: {type: 'function', value: null, optional: true},
  onDragStart: {type: 'function', value: null, optional: true},
  onDrag: {type: 'function', value: null, optional: true},
  onDragEnd: {type: 'function', value: null, optional: true},

  coordinateSystem: {
    type: 'object',
    value: 'default',
    validate: value => typeof value === 'string' || (Boolean(value) && typeof value === 'object'),
    equal: areCRSEqual
  },
  coordinateOrigin: {type: 'array', value: [0, 0, 0], compare: true},
  modelMatrix: {type: 'array', value: null, compare: true, optional: true},
  wrapLongitude: false,
  positionFormat: 'XYZ',
  colorFormat: 'RGBA',

  parameters: {type: 'object', value: {}, optional: true, compare: 2},
  loadOptions: {type: 'object', value: null, optional: true, ignore: true},
  transitions: null,
  extensions: [],
  loaders: {type: 'array', value: [], optional: true, ignore: true},

  // Offset depth based on layer index to avoid z-fighting.
  // Negative values pull layer towards the camera
  // https://www.opengl.org/archives/resources/faq/technical/polygonoffset.htm
  getPolygonOffset: {
    type: 'function',
    value: ({layerIndex}) => [0, -layerIndex * 100]
  },

  // Selection/Highlighting
  highlightedObjectIndex: null,
  autoHighlight: false,
  highlightColor: {type: 'accessor', value: DEFAULT_HIGHLIGHT_COLOR}
};

export type UpdateParameters<LayerT extends Layer> = {
  props: LayerT['props'];
  oldProps: LayerT['props'];
  context: LayerContext;
  changeFlags: ChangeFlags;
};

type DrawOptions = {
  renderPass: RenderPass;
  shaderModuleProps: any;
  uniforms: any;
  parameters: any;
  context: LayerContext;
};

type SharedLayerState = {
  /** CRS of source positions and their CPU conversion into packed attributes. */
  sourceCrs?: CRSDescriptor | null;
  packedCrs?: CRSDescriptor | null;
  preproject?: ((position: number[]) => [number, number, number]) | null;
  unpreproject?: ((position: number[]) => [number, number, number]) | null;
  [key: string]: unknown;
};

export default abstract class Layer<PropsT extends {} = {}> extends Component<
  PropsT & Required<LayerProps>
> {
  static defaultProps: DefaultProps = defaultProps;
  static layerName: string = 'Layer';

  static override get componentName() {
    return Object.prototype.hasOwnProperty.call(this, 'layerName') ? this.layerName : '';
  }

  internalState: LayerState<this> | null = null;
  lifecycle: Lifecycle = LIFECYCLE.NO_STATE; // Helps track and debug the life cycle of the layers

  // context and state can technically be null before a layer is initialized/matched.
  // However, they are most extensively accessed in a layer's lifecycle methods, where they are always defined.
  // Checking for null state constantly in layer implementation is unnecessarily verbose.
  context!: LayerContext; // Will reference layer manager's context, contains state shared by layers
  private _sourceCrs?: CRSDescriptor | null;
  private _coordinateSystemLoading = false;
  state!: SharedLayerState; // Will be set to the shared layer state object during layer matching

  parent: Layer | null = null;

  get root(): Layer {
    // eslint-disable-next-line
    let layer: Layer = this;
    while (layer.parent) {
      layer = layer.parent;
    }
    return layer;
  }

  toString(): string {
    const className = (this.constructor as typeof Layer).layerName || this.constructor.name;
    return `${className}({id: '${this.props.id}'})`;
  }

  // Public API for users

  /** Projects a point with current view state from the current layer's coordinate system to screen */
  project(xyz: number[]): number[] {
    assert(this.internalState);
    const viewport = this.internalState.viewport || this.context.viewport;

    const worldPosition = this.projectPosition(xyz, {autoOffset: false});
    const [x, y, z] = worldToPixels(worldPosition, viewport.pixelProjectionMatrix);
    return xyz.length === 2 ? [x, y] : [x, y, z];
  }

  /** Unprojects a screen pixel to the current view's default coordinate system
      Note: this does not reverse `project`. */
  unproject(xy: number[]): number[] {
    assert(this.internalState);
    const viewport = this.internalState.viewport || this.context.viewport;
    return viewport.unproject(xy);
  }

  /** Projects a point from the layer's coordinate system to common space, with optional parameter overrides. */
  projectPosition(
    xyz: number[],
    params: {
      /** The viewport to use */
      viewport?: Viewport;
      /** The model matrix to apply. Defaults to the layer prop; null disables it. */
      modelMatrix?: NumericArray | null;
      /** Absolute CRS of the supplied point. Defaults to the layer's resolved CRS. */
      sourceCrs?: CRSDescriptor;
      /** Select local coordinates or meter offsets, taking precedence over sourceCrs. */
      coordinateSystem?: 'cartesian' | 'meter-offsets';
      /** Input origin applied before conversion. Defaults to the layer prop. */
      coordinateOrigin?: [number, number, number];
      /** Whether to use the shader's automatic common-space offset for precision.
       * Set to false for absolute common-space coordinates. Default true. */
      autoOffset?: boolean;
    } = {}
  ): [number, number, number] {
    assert(this.internalState);
    const {
      viewport = this.internalState.viewport || this.context.viewport,
      sourceCrs = this.internalState.sourceCrs,
      coordinateSystem = params.sourceCrs?.signature ?? this.props.coordinateSystem,
      modelMatrix = this.props.modelMatrix,
      coordinateOrigin = this.props.coordinateOrigin,
      autoOffset
    } = params;
    return projectPosition(xyz, {
      viewport,
      sourceCrs,
      coordinateSystem,
      modelMatrix,
      coordinateOrigin,
      autoOffset
    });
  }

  // Public API for custom layer implementation

  /** `true` if this layer renders other layers */
  get isComposite(): boolean {
    return false;
  }

  /** `true` if the layer renders to screen */
  get isDrawable(): boolean {
    return true;
  }

  /** Updates selected state members and marks the layer for redraw */
  setState(partialState: any): void {
    this.setChangeFlags({stateChanged: true});
    Object.assign(this.state, partialState);
    this.setNeedsRedraw();
  }

  /** Sets the redraw flag for this layer, will trigger a redraw next animation frame */
  setNeedsRedraw(): void {
    if (this.internalState) {
      this.internalState.needsRedraw = true;
    }
  }

  /** Mark this layer as needs a deep update */
  setNeedsUpdate() {
    if (this.internalState) {
      this.context.layerManager.setNeedsUpdate(String(this));
      this.internalState.needsUpdate = true;
    }
  }

  /** Returns true if all async resources are loaded */
  get isLoaded(): boolean {
    return this.internalState
      ? !this._coordinateSystemLoading &&
          !this.internalState.isAsyncPropLoading() &&
          !this.internalState.accessorQueries?.pending
      : false;
  }

  /** Whether the source CRS is available for lifecycle and draw operations. */
  get isCoordinateSystemLoaded(): boolean {
    return !this._coordinateSystemLoading;
  }

  /** (Internal) Install a resolved source CRS, or block the layer while it loads. */
  _setSourceCrs(sourceCrs: CRSDescriptor | null | undefined): void {
    this._coordinateSystemLoading = sourceCrs === undefined;
    if (sourceCrs === undefined) return;
    this._sourceCrs = sourceCrs;
    if (this.internalState) {
      this.internalState.sourceCrs = sourceCrs;
      this._updatePreprojection(this.internalState.viewport || this.context.viewport);
    }
  }

  private _updatePreprojection(viewport: Viewport): boolean {
    const internalState = this.internalState!;
    const needsPreprojection = !supportsSourceCRS(
      viewport.projectionMode,
      internalState.sourceCrs,
      viewport.crs
    );
    // Only the source-to-packed conversion affects attributes. Camera precision,
    // target common space and subdivision are handled separately from packing.
    const signature = JSON.stringify([
      internalState.sourceCrs?.signature,
      needsPreprojection
        ? viewport.projectionMode === PROJECTION_MODE.CUSTOM_GEOSPATIAL
          ? viewport.crs?.signature
          : 'WGS84'
        : null
    ]);
    const changed = internalState.preprojectionSignature !== signature;
    if (changed) {
      Object.assign(internalState, viewport.getPreprojection(internalState.sourceCrs));
      internalState.preprojectionSignature = signature;
      internalState.preprojectionChanged = true;
    }
    const tessellationSignature = JSON.stringify([
      viewport.crs?.signature,
      viewport.projectionSignature
    ]);
    const geometryChanged = internalState.tessellationSignature !== tessellationSignature;
    internalState.tessellationSignature = tessellationSignature;
    // Subclasses can replace state during initializeState; publish the retained pair
    // again before updates without allocating new conversion functions each frame.
    Object.assign(this.state, {
      sourceCrs: internalState.sourceCrs,
      packedCrs: internalState.packedCrs,
      preproject: internalState.preproject,
      unpreproject: internalState.unpreproject
    });
    if ((changed || geometryChanged) && internalState.changeFlags) {
      this.setChangeFlags({projectionChanged: true});
    }
    return changed || geometryChanged;
  }

  /** Returns true if using shader-based WGS84 longitude wrapping */
  get wrapLongitude(): boolean {
    return this.props.wrapLongitude;
  }

  /** @deprecated Returns true if the layer is visible in the picking pass */
  isPickable(): boolean {
    return this.props.pickable && this.props.visible;
  }

  /** Returns the rendering models used by this layer, including GPU-vector models. */
  getModels(): LumaGPUVectorModel[] {
    const state = this.state as {
      models?: LumaGPUVectorModel[];
      model: LumaGPUVectorModel;
    };
    return (state && (state.models || (state.model && [state.model]))) || [];
  }

  /** Update shader input parameters */
  setShaderModuleProps(...props: Parameters<Model['shaderInputs']['setProps']>): void {
    for (const model of this.getModels()) {
      model.shaderInputs.setProps(...props);
    }
  }

  /** Returns the attribute manager of this layer */
  getAttributeManager(): AttributeManager | null {
    return this.internalState && this.internalState.attributeManager;
  }

  /** Returns the most recent layer that matched to this state
    (When reacting to an async event, this layer may no longer be the latest) */
  getCurrentLayer(): Layer<PropsT> | null {
    return this.internalState && this.internalState.layer;
  }

  /** Returns the default parse options for async props */
  getLoadOptions(): any {
    return this.props.loadOptions;
  }

  /** Opt an attribute into source-CRS conversion and automatic position invalidation.
   * The transform is refreshed when the source CRS or viewport changes.
   */
  usePositionTransforms(): Pick<AttributeOptions, 'transformSource' | 'transform'> {
    return {
      transformSource: 'projection',
      transform: this.internalState?.preproject ? transformPosition : null
    };
  }

  /** Subdivision step in accessor coordinates, accounting for the layer model matrix.
   * @internal Tessellators subdivide before model-matrix and CRS conversion.
   */
  getSubdivisionStep(): number {
    const sourceCrs = this.internalState?.sourceCrs;
    if (!sourceCrs) return 0;
    const step = this.context.viewport.getSubdivisionStep(sourceCrs);
    const {modelMatrix} = this.props;
    if (!step || !modelMatrix) return step;
    // A tile's matrix scales normalized local positions into CRS world units.
    // Translation does not change the interval; use the larger horizontal axis scale.
    const scale = Math.max(
      Math.hypot(modelMatrix[0], modelMatrix[1], modelMatrix[2]),
      Math.hypot(modelMatrix[4], modelMatrix[5], modelMatrix[6])
    );
    return scale > 0 ? step / scale : 0;
  }

  use64bitPositions(): boolean {
    const {coordinateSystem} = this.props;
    return (
      Boolean(this.internalState?.sourceCrs) ||
      this.context?.viewport?.projectionMode === PROJECTION_MODE.CUSTOM_GEOSPATIAL ||
      coordinateSystem === 'default' ||
      coordinateSystem === 'lnglat' ||
      coordinateSystem === 'cartesian'
    );
  }

  // Event handling
  onHover(info: PickingInfo, pickingEvent): boolean {
    if (this.props.onHover) {
      return this.props.onHover(info, pickingEvent) || false;
    }
    return false;
  }

  onClick(info: PickingInfo, pickingEvent): boolean {
    if (this.props.onClick) {
      return this.props.onClick(info, pickingEvent) || false;
    }
    return false;
  }

  // Returns the picking color that doesn't match any subfeature
  // Use if some graphics do not belong to any pickable subfeature
  // @return {Array} - a black color
  nullPickingColor() {
    return [0, 0, 0];
  }

  // Returns the picking color that doesn't match any subfeature
  // Use if some graphics do not belong to any pickable subfeature
  encodePickingColor(i, target: number[] = []): [number, number, number] {
    target[0] = (i + 1) & 255;
    target[1] = ((i + 1) >> 8) & 255;
    target[2] = (((i + 1) >> 8) >> 8) & 255;
    return target as [number, number, number];
  }

  // Returns the index corresponding to a picking color that doesn't match any subfeature
  // @param {Uint8Array} color - color array to be decoded
  // @return {Array} - the decoded picking color
  decodePickingColor(color) {
    assert(color instanceof Uint8Array);
    const [i1, i2, i3] = color;
    // 1 was added to seperate from no selection
    const index = i1 + i2 * 256 + i3 * 65536 - 1;
    return index;
  }

  /** Deduces number of instances. Intention is to support:
    - Explicit setting of numInstances
    - Auto-deduction for ES6 containers that define a size member
    - Auto-deduction for Classic Arrays via the built-in length attribute
    - Auto-deduction via arrays */
  getNumInstances(): number {
    // First Check if app has provided an explicit value
    if (Number.isFinite(this.props.numInstances)) {
      return this.props.numInstances as number;
    }

    // Second check if the layer has set its own value
    if (this.state && this.state.numInstances !== undefined) {
      return this.state.numInstances as number;
    }

    // Use container library to get a count for any ES6 container or object
    return count(this.getColumnData());
  }

  /** Buffer layout describes how many attribute values are packed for each data object
      The default (null) is one value each object.
      Some data formats (e.g. paths, polygons) have various length. Their buffer layout
      is in the form of [L0, L1, L2, ...] */
  getStartIndices(): NumericArray | null {
    // First Check if startIndices is provided as an explicit value
    if (this.props.startIndices) {
      return this.props.startIndices;
    }

    // Second check if the layer has set its own value
    if (this.state && this.state.startIndices) {
      return this.state.startIndices as NumericArray;
    }

    return null;
  }

  // Default implementation
  getBounds(): [number[], number[]] | null {
    return this.getAttributeManager()?.getBounds(['positions', 'instancePositions']);
  }

  // / LIFECYCLE METHODS - overridden by the layer subclasses

  /**
   * Returns selected column inputs, optionally including compatible fields from loaded Arrow data.
   * Explicit props take precedence. Unselected columns use binary attributes or accessors.
   * Selected inputs are returned without conversion or ownership changes.
   */
  protected resolveColumns(
    definitions: ColumnDefinitions,
    useTable = false
  ): Record<string, unknown> {
    const data = useTable ? this.getColumnData() : this.props.data;
    const props =
      data === this.props.data ? this.props : Object.create(this.props, {data: {value: data}});
    return resolveColumns(props, definitions, useTable);
  }

  /** Returns the table used by column-aware layers while leaving the loaded prop intact. */
  protected getColumnData(): LayerData<unknown> {
    const data = unwrapLoaderArrowResult(this.props.data) as LayerData<unknown>;
    if (
      Array.isArray(data) &&
      data.length === 0 &&
      !this.internalState?.isAsyncPropLoading('data')
    ) {
      const columns = this.props[ROW_ACCESSOR_COLUMNS_SYMBOL];
      for (const [name, column] of Object.entries(columns ?? {})) {
        const type = this.props[PROP_TYPES_SYMBOL][name];
        if (
          type?.type === 'accessor' &&
          'arrowWithExtensions' in type &&
          type.arrowWithExtensions
        ) {
          return {length: column.length};
        }
      }
    }
    return data;
  }

  /** Merges Deck and layer declarations by SQL name, with the layer taking precedence. */
  private getSQLFunctions() {
    return Array.from(
      new Map(
        [...(this.context.sqlFunctions ?? []), ...(this.props.sqlFunctions ?? [])].map(fn => [
          fn.name.toUpperCase(),
          fn
        ])
      ).values()
    );
  }

  /** Evaluates opted-in SQL accessors against the loaded data, preserving source row order. */
  private updateAccessorQueries(): void {
    const state = this.internalState!;
    const queries = this.props[ACCESSOR_QUERIES_SYMBOL];
    if (!queries) {
      state.accessorQueries = undefined;
      return;
    }
    const source = this.props.data;
    if (
      source == null ||
      (Array.isArray(source) && source.length === 0) ||
      (state.isAsyncPropLoading('data') && !isArrowTable(unwrapLoaderArrowResult(source)))
    ) {
      state.accessorQueries = undefined;
      return;
    }
    const parseExpression = this.context.sqlParser?.parseExpression;
    const functions = this.getSQLFunctions();
    const expressions = Object.fromEntries(
      Object.entries(queries).map(([name, query]) => [name, query.sql])
    );
    const previous = state.accessorQueries;
    const matches = (layer: Layer) => {
      const inputs = layer.props[ACCESSOR_QUERIES_SYMBOL];
      return (
        inputs &&
        layer.props.data === source &&
        layer.context.sqlParser?.parseExpression === parseExpression &&
        deepEqual(layer.getSQLFunctions(), functions, 1) &&
        Object.keys(inputs).length === Object.keys(expressions).length &&
        Object.entries(expressions).every(([name, sql]) => inputs[name]?.sql === sql)
      );
    };
    const apply = (layer: Layer, columns: NonNullable<typeof previous>['columns']) => {
      for (const [name, input] of Object.entries(layer.props[ACCESSOR_QUERIES_SYMBOL]!)) {
        input.column = columns?.[name];
      }
    };
    if (
      previous &&
      previous.source === source &&
      previous.parseExpression === parseExpression &&
      deepEqual(previous.functions, functions, 1) &&
      deepEqual(previous.expressions, expressions, 1)
    ) {
      apply(this, previous.columns);
      return;
    }

    const request: NonNullable<typeof state.accessorQueries> = {
      source,
      expressions,
      parseExpression,
      functions,
      scales: previous?.scales,
      pending: true
    };
    state.accessorQueries = request;
    apply(this, undefined);

    const currentLayer = () => {
      const layer = state.layer;
      return state.accessorQueries === request && layer && matches(layer) ? layer : null;
    };
    void import('../arrow/accessor-queries')
      .then(({evaluateAccessorQueries}) =>
        evaluateAccessorQueries(source, expressions, parseExpression, previous, functions)
      )
      .then(
        ({table, scales}) => {
          const layer = currentLayer();
          if (layer) {
            request.table = table;
            request.scales = Object.keys(scales).length ? scales : undefined;
            request.pending = false;
            request.columns = Object.fromEntries(
              Object.keys(expressions).map(name => [name, table.getChild(name)!])
            );
            apply(layer, request.columns);
            layer.setChangeFlags({dataChanged: 'SQL accessors resolved'});
            layer.setNeedsUpdate();
          }
        },
        error => {
          const layer = currentLayer();
          if (layer) {
            request.scales = undefined;
            request.pending = false;
            layer.setNeedsUpdate();
            layer.raiseError(error, 'evaluating SQL accessors');
            layer.setChangeFlags({dataChanged: 'SQL accessor evaluation failed'});
          }
        }
      );
  }

  /** Returns whether the caller supplied a SQL expression for this accessor. */
  protected hasAccessorQuery(name: string): boolean {
    return Boolean(this.props[ACCESSOR_QUERIES_SYMBOL]?.[name]);
  }

  /** Returns the current row-aligned SQL accessor results with their Arrow field metadata. */
  protected getAccessorQueryTable() {
    return this.internalState?.accessorQueries?.table;
  }

  /**
   * Experimental. Returns resolved SQL color scales keyed by accessor. The result is undefined
   * until the first evaluation completes. While updating, it describes the previously applied
   * colors.
   * Color samples use normalized RGBA channels in [0, 1].
   */
  _getResolvedColorScales(): Readonly<Record<string, ResolvedScale>> | undefined {
    return this.internalState?.accessorQueries?.scales;
  }

  /** Called once to set up the initial state. Layers can create WebGL resources here. */
  abstract initializeState(context: LayerContext): void;

  /**
   * Returns shader options and the deck.gl assembler used by layer models.
   * Supply a subset of extensions when assembling a dedicated render pass.
   */
  getShaders(shaders: any, extensions = this.props.extensions): any {
    // Preprojection capability is stable for the lifetime of a layer instance.
    shaders = mergeShaders(
      {
        defines: {
          USE_EXTERNAL_PROJECTION:
            this.context.viewport.projectionMode === PROJECTION_MODE.CUSTOM_GEOSPATIAL
        }
      },
      shaders
    );
    // Preserve the public picking module contract while installing its injection target contributions.
    if (shaders.modules?.includes(pickingModule) && !shaders.plugins?.includes(pickingPlugin)) {
      shaders = mergeShaders(shaders, {plugins: [pickingPlugin]});
    }
    shaders = mergeShaders(shaders, {
      disableWarnings: true,
      modules: this.context.defaultShaderModules,
      plugins: this.context.defaultShaderPlugins
    });
    for (const extension of extensions) {
      shaders = mergeShaders(shaders, extension.getShaders.call(this, extension));
    }
    return {...shaders, shaderAssembler: this.context.shaderAssembler};
  }

  /** Controls if updateState should be called. By default returns true if any prop has changed */
  shouldUpdateState(params: UpdateParameters<Layer<PropsT>>): boolean {
    return params.changeFlags.propsOrDataChanged;
  }

  /** Default implementation, all attributes will be invalidated and updated when data changes */
  // eslint-disable-next-line complexity
  updateState(params: UpdateParameters<Layer<PropsT>>): void {
    const attributeManager = this.getAttributeManager();
    const {dataChanged} = params.changeFlags;
    if (dataChanged && attributeManager) {
      if (Array.isArray(dataChanged)) {
        // is partial update
        for (const dataRange of dataChanged) {
          attributeManager.invalidateAll(dataRange);
        }
      } else {
        attributeManager.invalidateAll();
      }
    }

    // Enable/disable picking buffer
    if (attributeManager) {
      const {props} = params;
      const hasPickingBuffer = this.internalState!.hasPickingBuffer;
      const needsPickingBuffer =
        Number.isInteger(props.highlightedObjectIndex) ||
        Boolean(props.pickable) ||
        props.extensions.some(extension => extension.getNeedsPickingBuffer.call(this, extension));

      // Only generate picking buffer if needed
      if (hasPickingBuffer !== needsPickingBuffer) {
        this.internalState!.hasPickingBuffer = needsPickingBuffer;
        const pickingAttribute = getPickingAttribute(attributeManager.attributes);
        if (pickingAttribute) {
          if (needsPickingBuffer && pickingAttribute.constant) {
            pickingAttribute.constant = false;
            attributeManager.invalidate(pickingAttribute.id);
          }
          if (!pickingAttribute.value && !needsPickingBuffer) {
            pickingAttribute.constant = true;
            pickingAttribute.value = getPickingIndexAttribute(attributeManager.attributes)
              ? [PICKING_INVALID_INDEX]
              : [0, 0, 0];
          }
        }
      }
    }
  }

  /** Called once when layer is no longer matched and state will be discarded. Layers can destroy WebGL resources here. */
  finalizeState(context: LayerContext): void {
    for (const model of this.getModels()) {
      model.destroy();
    }
    const attributeManager = this.getAttributeManager();
    if (attributeManager) {
      attributeManager.finalize();
    }
    if (this.context) {
      this.context.resourceManager.unsubscribe({consumerId: this.id});
    }
    if (this.internalState) {
      this.internalState.uniformTransitions.clear();
      this.internalState.finalize();
    }
  }

  // If state has a model, draw it with supplied uniforms
  draw(opts: DrawOptions) {
    for (const model of this.getModels()) {
      model.draw(opts.renderPass);
    }
  }

  // called to populate the info object that is passed to the event handler
  // @return null to cancel event
  getPickingInfo({info, mode, sourceLayer}: GetPickingInfoParams) {
    const {index} = info;

    if (index >= 0) {
      const data = this.getColumnData();
      if (Array.isArray(data)) {
        info.object = data[index];
      } else if (isArrowTable(data)) {
        info.object = data.get(index);
      }
    }

    return info;
  }

  // END LIFECYCLE METHODS

  // / INTERNAL METHODS - called by LayerManager, DeckRenderer and DeckPicker

  /** (Internal) Propagate an error event through the system */
  raiseError(error: Error, message: string): void {
    if (message) {
      // Duplicating error message for backward compatibility, see #7986
      // TODO - revisit in v9
      error = new Error(`${message}: ${error.message}`, {cause: error});
    }
    if (!this.props.onError?.(error)) {
      this.context?.onError?.(error, this);
    }
  }

  /** (Internal) Checks if this layer needs redraw */
  getNeedsRedraw(
    opts: {
      /** Reset redraw flags to false after the check */
      clearRedrawFlags: boolean;
    } = {clearRedrawFlags: false}
  ): string | false {
    return this._getNeedsRedraw(opts);
  }

  /** (Internal) Checks if this layer needs a deep update */
  needsUpdate(): boolean {
    if (!this.internalState) {
      return false;
    }

    // Call subclass lifecycle method
    return (
      this.internalState.needsUpdate ||
      this.internalState.changeFlags.projectionChanged ||
      this.hasUniformTransition() ||
      this.shouldUpdateState(this._getUpdateParams())
    );
    // End lifecycle method
  }

  /** Checks if this layer has ongoing uniform transition */
  hasUniformTransition(): boolean {
    return this.internalState?.uniformTransitions.active || false;
  }

  /** Called when this layer is rendered into the given viewport */
  activateViewport(viewport: Viewport): void {
    if (!this.internalState) {
      return;
    }

    if (!this.context.layerManager.isViewportReady(this)) return;
    const oldViewport = this.internalState.viewport;
    this.internalState.viewport = viewport;
    if (this._coordinateSystemLoading) return;
    const projectionChanged = this._updatePreprojection(viewport);

    if (!oldViewport || !areViewportsEqual({oldViewport, viewport})) {
      this.setChangeFlags({
        viewportChanged: true,
        projectionChanged
      });

      if (this.isComposite) {
        if (this.needsUpdate()) {
          // Composite layers may add/remove sublayers on viewport change
          // Because we cannot change the layers list during a draw cycle, we don't want to update sublayers right away
          // This will not call update immediately, but mark the layerManager as needs update on the next frame
          this.setNeedsUpdate();
        }
      } else {
        this._update();
      }
    }
  }

  /** Default implementation of attribute invalidation, can be redefined */
  protected invalidateAttribute(name = 'all'): void {
    const attributeManager = this.getAttributeManager();
    if (!attributeManager) {
      return;
    }

    if (name === 'all') {
      attributeManager.invalidateAll();
    } else {
      attributeManager.invalidate(name);
    }
  }

  /** Send updated attributes to the WebGL model */
  protected updateAttributes(changedAttributes: {[id: string]: Attribute}) {
    // If some buffer layout changed
    let bufferLayoutChanged = false;
    for (const id in changedAttributes) {
      if (changedAttributes[id].layoutChanged()) {
        bufferLayoutChanged = true;
      }
    }

    const attributeManager = this.getAttributeManager();
    const bufferGroupsUpdated = Boolean(attributeManager?.hasBufferGroups());
    if (bufferGroupsUpdated) {
      // Models share packed storage; uploading per model would destroy earlier bindings.
      attributeManager!.getBufferGroupBindings(changedAttributes);
    }
    for (const model of this.getModels()) {
      this._setModelAttributes(model, changedAttributes, bufferLayoutChanged, bufferGroupsUpdated);
    }
  }

  /** Returns the Deck input convention for a top-level layer. Composite children keep byte colors. */
  protected usesNormalizedColors(): boolean {
    return !this.parent && Boolean(this.context.normalizedColors);
  }

  /** Recalculate any attributes if needed */
  protected _updateAttributes(): void {
    const attributeManager = this.getAttributeManager();
    if (!attributeManager) {
      return;
    }
    const props = this.props;

    const normalizedColorInput = this.usesNormalizedColors();
    for (const attribute of Object.values(attributeManager.attributes)) {
      const {settings} = attribute;
      if (
        settings.semanticType === 'color' &&
        settings.normalizedColorInput !== normalizedColorInput
      ) {
        settings.normalizedColorInput = normalizedColorInput;
        attribute.setNeedsUpdate();
      }
    }

    // Figure out data length
    const numInstances = this.getNumInstances();
    const startIndices = this.getStartIndices();

    const data = this.getColumnData();
    attributeManager.update({
      data,
      numInstances,
      startIndices,
      props,
      transitions: props.transitions,
      // @ts-ignore (TS2339) property attribute is not present on some acceptable data types
      buffers: data.attributes,
      context: this
    });

    const changedAttributes = attributeManager.getChangedAttributes({clearChangedFlags: true});
    this.updateAttributes(changedAttributes);
  }

  /** Update attribute transitions. This is called in drawLayer, no model updates required. */
  private _updateAttributeTransition() {
    const attributeManager = this.getAttributeManager();
    if (attributeManager) {
      attributeManager.updateTransition();
    }
  }

  /** Converts a prop to its interpolation representation before a uniform transition starts. */
  protected getUniformTransitionValue(_propName: string, value: unknown): unknown {
    return value;
  }

  /** Returns whether the current prop value is an interpolated uniform transition value. */
  protected isUniformTransitionValue(propName: string): boolean {
    return !Object.hasOwn(this.props, COMPONENT_SYMBOL) && Object.hasOwn(this.props, propName);
  }

  /** Update uniform (prop) transitions. This is called in updateState, may result in model updates. */
  private _updateUniformTransition(): Layer<PropsT>['props'] {
    // @ts-ignore (TS2339) internalState is alwasy defined when this method is called
    const {uniformTransitions} = this.internalState;
    if (uniformTransitions.active) {
      // clone props
      const propsInTransition = uniformTransitions.update();
      const props = Object.create(this.props);
      for (const key in propsInTransition) {
        Object.defineProperty(props, key, {value: propsInTransition[key]});
      }
      return props;
    }
    return this.props;
  }

  /** Updater for the automatically populated instancePickingColors attribute */
  protected calculateInstancePickingColors(
    attribute: Attribute,
    {numInstances}: {numInstances: number}
  ) {
    if (attribute.constant) {
      return;
    }

    // calculateInstancePickingColors always generates the same sequence.
    // pickingColorCache saves the largest generated sequence for reuse
    const cacheSize = Math.floor(pickingColorCache.length / 4);

    // Record when using the picking buffer cache, so that layers can always point at the most recently allocated cache
    // @ts-ignore (TS2531) internalState is always defined when this method is called
    this.internalState.usesPickingColorCache = true;

    const isPickingColorCacheInvalid = numInstances > 0 && pickingColorCache[0] === 0;
    if (cacheSize < numInstances || isPickingColorCacheInvalid) {
      if (numInstances > MAX_PICKING_COLOR_CACHE_SIZE) {
        log.warn(
          'Layer has too many data objects. Picking might not be able to distinguish all objects.'
        )();
      }

      pickingColorCache = typedArrayManager.allocate(pickingColorCache, numInstances, {
        size: 4,
        copy: true,
        maxCount: Math.max(numInstances, MAX_PICKING_COLOR_CACHE_SIZE)
      });

      // If the attribute is larger than the cache, resize the cache and populate the missing chunk
      const newCacheSize = Math.floor(pickingColorCache.length / 4);
      const pickingColor: [number, number, number] = [0, 0, 0];
      const startIndex = isPickingColorCacheInvalid ? 0 : cacheSize;
      for (let i = startIndex; i < newCacheSize; i++) {
        this.encodePickingColor(i, pickingColor);
        pickingColorCache[i * 4 + 0] = pickingColor[0];
        pickingColorCache[i * 4 + 1] = pickingColor[1];
        pickingColorCache[i * 4 + 2] = pickingColor[2];
        pickingColorCache[i * 4 + 3] = 0;
      }
    }

    attribute.value = pickingColorCache.subarray(0, numInstances * 4);
  }

  private _setGPUVectorModelAttributes(
    model: GPUVectorModel,
    attributeManager: AttributeManager,
    changedAttributes: Record<string, Attribute>
  ): void {
    const excludeAttributes = (model.userData?.excludeAttributes || {}) as Record<string, boolean>;
    const bindings = attributeManager.getBufferGroupBindings(
      changedAttributes,
      model,
      excludeAttributes
    );
    const attributes = {...attributeManager.getAttributes()};
    let indexBuffer: Buffer | null | undefined;
    for (const name in attributes) {
      if (excludeAttributes[name] || bindings.groupedAttributeIds.has(name)) {
        delete attributes[name];
      } else if (attributes[name].settings.isIndexed) {
        indexBuffer = attributes[name].getBuffer();
        delete attributes[name];
      }
    }
    const columns = attributeManager.getGPUVectors(attributes, {
      ...bindings,
      length: this.getNumInstances()
    });
    model.setGPUAttributes(columns, bindings.bufferLayouts);
    if (indexBuffer !== undefined) {
      model.setIndexBuffer(indexBuffer);
    }
  }

  /** Apply changed attributes to a rendering model or texture transform model. */
  // eslint-disable-next-line max-statements
  protected _setModelAttributes(
    model: Model | LumaGPUVectorModel,
    changedAttributes: {
      [id: string]: Attribute;
    },
    bufferLayoutChanged = false,
    bufferGroupsUpdated = false
  ) {
    if (!Object.keys(changedAttributes).length) {
      return;
    }

    const attributeManager = this.getAttributeManager();
    const changedGroupAttributes = bufferGroupsUpdated ? {} : changedAttributes;
    if (model instanceof GPUVectorModel && attributeManager) {
      this._setGPUVectorModelAttributes(model, attributeManager, changedGroupAttributes);
      return;
    }
    if (attributeManager?.hasBufferGroups()) {
      this._setGroupedModelAttributes(model, attributeManager, changedGroupAttributes);
      return;
    }

    if (bufferLayoutChanged) {
      // AttributeManager is always defined when this method is called
      const manager = this.getAttributeManager()!;
      model.setBufferLayout(manager.getBufferLayouts(model));
      // All attributes must be reset after buffer layout change
      changedAttributes = manager.getAttributes();
    }

    const excludeAttributes = (model.userData?.excludeAttributes || {}) as Record<string, boolean>;
    const attributeBuffers: Record<string, Buffer> = {};
    const constantAttributes: Record<string, TypedArray> = {};

    for (const name in changedAttributes) {
      if (excludeAttributes[name]) {
        continue;
      }
      const values = changedAttributes[name].getValue();
      for (const attributeName in values) {
        const value = values[attributeName];
        if (value instanceof Buffer) {
          if (changedAttributes[name].settings.isIndexed) {
            model.setIndexBuffer(value);
          } else {
            attributeBuffers[attributeName] = value;
          }
        } else if (value) {
          constantAttributes[attributeName] = value;
        }
      }
    }
    // TODO - update buffer map?
    model.setAttributes(attributeBuffers);
    model.setConstantAttributes(constantAttributes);
  }

  /** Apply explicit WebGPU buffer groups while preserving legacy bindings for fallbacks. */
  private _setGroupedModelAttributes(
    model: Model | LumaGPUVectorModel,
    attributeManager: AttributeManager,
    changedAttributes: {[id: string]: Attribute}
  ) {
    const excludeAttributes = (model.userData?.excludeAttributes || {}) as Record<string, boolean>;
    const bindings = attributeManager.getBufferGroupBindings(
      changedAttributes,
      model,
      excludeAttributes
    );

    // Runtime state can make a declared group temporarily ineligible, e.g. during transitions.
    // Refreshing the layout here lets the group safely fall back to standalone bindings.
    model.setBufferLayout(bindings.bufferLayouts);

    const attributeBuffers: Record<string, Buffer> = {...bindings.buffers};
    const constantAttributes: Record<string, TypedArray> = {};
    const attributes = attributeManager.getAttributes();

    for (const name in attributes) {
      if (excludeAttributes[name] || bindings.groupedAttributeIds.has(name)) {
        continue;
      }
      const attribute = attributes[name];
      const values = attribute.getValue();
      for (const attributeName in values) {
        const value = values[attributeName];
        if (value instanceof Buffer) {
          if (attribute.settings.isIndexed) {
            model.setIndexBuffer(value);
          } else {
            attributeBuffers[attributeName] = value;
          }
        } else if (value) {
          constantAttributes[attributeName] = value;
        }
      }
    }

    model.setAttributes(attributeBuffers);
    model.setConstantAttributes(constantAttributes);
  }

  /** (Internal) Sets the picking color at the specified index to null picking color. Used for multi-depth picking.
     This method may be overriden by layer implementations */
  disablePickingIndex(objectIndex: number) {
    const data = this.props.data as LayerData<any>;
    if (!('attributes' in data) || isArrowTable(data)) {
      this._disablePickingIndex(objectIndex);
      return;
    }

    const attributes = this.getAttributeManager()?.getAttributes() || {};
    const indexes = getPickingIndexAttribute(attributes);
    const colors = getPickingColorAttribute(attributes);

    const externalIndexAttribute =
      indexes && data.attributes && (data.attributes[indexes.id] as BinaryAttribute);
    if (externalIndexAttribute && externalIndexAttribute.value) {
      const values = externalIndexAttribute.value;
      for (let index = 0; index < data.length; index++) {
        const i = indexes.getVertexOffset(index);
        if (values[i] === objectIndex) {
          this._disablePickingIndex(index);
        }
      }
      return;
    }

    const externalColorAttribute =
      colors && data.attributes && (data.attributes[colors.id] as BinaryAttribute);
    if (externalColorAttribute && externalColorAttribute.value) {
      const values = externalColorAttribute.value;
      const objectColor = this.encodePickingColor(objectIndex);
      for (let index = 0; index < data.length; index++) {
        const i = colors.getVertexOffset(index);
        if (
          values[i] === objectColor[0] &&
          values[i + 1] === objectColor[1] &&
          values[i + 2] === objectColor[2]
        ) {
          this._disablePickingIndex(index);
        }
      }
    } else {
      this._disablePickingIndex(objectIndex);
    }
  }

  // TODO - simplify subclassing interface
  protected _disablePickingIndex(objectIndex: number): void {
    const attributes = this.getAttributeManager()?.getAttributes() || {};
    const indexes = getPickingIndexAttribute(attributes);
    if (indexes) {
      const start = indexes.getVertexOffset(objectIndex);
      const end = indexes.getVertexOffset(objectIndex + 1);
      const invalidIndexes = new Uint32Array(end - start);
      invalidIndexes.fill(PICKING_INVALID_INDEX);
      indexes.buffer.write(invalidIndexes, start * invalidIndexes.BYTES_PER_ELEMENT);
      return;
    }

    const colors = getPickingColorAttribute(attributes);
    if (!colors) {
      if (this.internalState) {
        disablePickingIndex(this.internalState.disabledPickingIndices, objectIndex);
      }
      return;
    }

    const start = colors.getVertexOffset(objectIndex);
    const end = colors.getVertexOffset(objectIndex + 1);

    // Fill the sub buffer with 0s, 1 byte per element
    colors.buffer.write(new Uint8Array(end - start), start);
  }

  /** (Internal) Re-enable all picking indices after multi-depth picking */
  restorePickingColors(): void {
    const attributes = this.getAttributeManager()?.getAttributes() || {};
    const pickingAttribute = getPickingAttribute(attributes);
    if (!pickingAttribute) {
      if (this.internalState) {
        this.internalState.disabledPickingIndices.length = 0;
      }
      return;
    }
    const colors = getPickingColorAttribute(attributes);
    // The picking color cache may have been freed and then reallocated. This ensures we read from the currently allocated cache.
    if (
      // @ts-ignore (TS2531) this method is only called internally with internalState defined
      this.internalState.usesPickingColorCache &&
      colors &&
      (colors.value as Uint8ClampedArray).buffer !== pickingColorCache.buffer
    ) {
      colors.value = pickingColorCache.subarray(0, (colors.value as Uint8ClampedArray).length);
    }
    pickingAttribute.updateSubBuffer({startOffset: 0});
  }

  /* eslint-disable max-statements */
  /* (Internal) Called by layer manager when a new layer is found */
  _initialize(initialViewport?: Viewport) {
    assert(!this.internalState); // finalized layer cannot be reused

    const previousViewport = this.context.viewport;
    // Initial projection and subclass setup must agree with the viewport selected
    // for this layer, before rendering has had a chance to activate it.
    this.context.viewport = initialViewport || previousViewport;
    try {
      debug(TRACE_INITIALIZE, this);

      const attributeManager = this._getAttributeManager();

      this.internalState = new LayerState<this>({
        attributeManager,
        layer: this
      });
      this.internalState.viewport = initialViewport;
      this._clearChangeFlags(); // populate this.internalState.changeFlags

      this.state = {};
      const coordinateSystem =
        (this.props.coordinateSystem ?? 'default') === 'default'
          ? this.context.viewport.isGeospatial
            ? 'WGS84'
            : 'cartesian'
          : this.props.coordinateSystem;
      const sourceCrs =
        this._sourceCrs === undefined ? resolveCRS(coordinateSystem) : this._sourceCrs;
      // LayerManager resolves asynchronous descriptors before initialization.
      assert(!(sourceCrs instanceof Promise));
      this.internalState.sourceCrs = sourceCrs;
      this._updatePreprojection(this.context.viewport);
      // for backwards compatibility with older layers
      // TODO - remove in next release
      /* eslint-disable accessor-pairs */
      Object.defineProperty(this.state, 'attributeManager', {
        get: () => {
          log.deprecated('layer.state.attributeManager', 'layer.getAttributeManager()')();
          return attributeManager;
        }
      });
      /* eslint-enable accessor-pairs */

      this.internalState.uniformTransitions = new UniformTransitionManager(this.context.timeline);
      this.internalState.onAsyncPropUpdated = this._onAsyncPropUpdated.bind(this);

      // Ensure any async props are updated
      this.internalState.setAsyncProps(this.props);

      // Call subclass lifecycle methods
      this.initializeState(this.context);

      // Initialize extensions
      for (const extension of this.props.extensions) {
        extension.initializeState.call(this, this.context, extension);
      }
      // End subclass lifecycle methods

      // initializeState callback tends to clear state
      this.setChangeFlags({
        dataChanged: 'init',
        propsChanged: 'init',
        viewportChanged: true,
        extensionsChanged: true
      });

      this._update();
    } finally {
      this.context.viewport = previousViewport;
    }
  }

  /** (Internal) Called by layer manager to transfer state from an old layer */
  _transferState(oldLayer: Layer<PropsT>): void {
    debug(TRACE_MATCHED, this, this === oldLayer);

    const {state, internalState} = oldLayer;

    if (this === oldLayer) {
      this.internalState?.refreshQueryParser();
      return;
    }

    // Move internalState
    this.internalState = internalState as LayerState<this>;

    // Move state
    this.state = state;
    // We keep the state ref on old layers to support async actions
    // oldLayer.state = null;

    // Ensure any async props are updated
    this.internalState.setAsyncProps(this.props);

    this.updateAccessorQueries();
    this._diffProps(this.props, this.internalState.getOldProps() as Layer<PropsT>['props']);
  }

  /** (Internal) Called by layer manager when a new layer is added or an existing layer is matched with a new instance */
  _update(): void {
    if (
      !this.internalState ||
      this._coordinateSystemLoading ||
      !this.context.layerManager.isViewportReady(this)
    )
      return;
    this._updatePreprojection(this.internalState?.viewport || this.context.viewport);
    this.updateAccessorQueries();
    // Keep the current attributes until the new rows and SQL columns can be applied together.
    if (this.internalState.accessorQueries?.pending) {
      return;
    }
    // Call subclass lifecycle method
    const stateNeedsUpdate = this.needsUpdate();
    // End lifecycle method
    debug(TRACE_UPDATE, this, stateNeedsUpdate);

    if (!stateNeedsUpdate) {
      return;
    }
    this.context.stats.get('Layer updates').incrementCount();

    const currentProps = this.props;
    const context = this.context;
    const internalState = this.internalState as LayerState<this>;

    const currentViewport = context.viewport;
    const propsInTransition = this._updateUniformTransition();
    internalState.propsInTransition = propsInTransition;
    // Use the first eligible viewport retained by this layer for lifecycle updates
    // In multi-view applications, a layer may only be drawn in one of the views
    // Which would make the "active" viewport different from the shared context
    context.viewport = internalState.viewport || currentViewport;
    // Overwrite this.props during update to use in-transition prop values
    this.props = propsInTransition;

    try {
      const updateParams = this._getUpdateParams();
      const oldModels = this.getModels();
      const coordinateSystemChanged = !areCRSEqual(
        updateParams.props.coordinateSystem,
        updateParams.oldProps.coordinateSystem
      );
      if (
        internalState.preprojectionChanged ||
        (this.internalState.preproject &&
          (coordinateSystemChanged ||
            !deepEqual(updateParams.props.modelMatrix, updateParams.oldProps.modelMatrix, 1) ||
            !deepEqual(
              updateParams.props.coordinateOrigin,
              updateParams.oldProps.coordinateOrigin,
              1
            )))
      ) {
        const attributeManager = this.getAttributeManager();
        for (const [name, attribute] of Object.entries(attributeManager?.attributes || {})) {
          if (attribute.settings.transformSource === 'projection') {
            // Layout-specific wrappers compose projection themselves; retain them
            // while refreshing only the transform installed by usePositionTransforms.
            if (
              'transform' in attribute.settings &&
              (!attribute.settings.transform || attribute.settings.transform === transformPosition)
            ) {
              attribute.settings.transform = this.usePositionTransforms().transform;
            }
            attributeManager!.invalidate(name);
          }
        }
      }

      // Safely call subclass lifecycle methods
      if (context.device) {
        this.updateState(updateParams);
      } else {
        try {
          this.updateState(updateParams);
        } catch (error) {
          // ignore error if gl context is missing
        }
      }
      // Execute extension updates
      for (const extension of this.props.extensions) {
        extension.updateState.call(this, updateParams, extension);
      }

      this.setNeedsRedraw();
      // Check if attributes need recalculation
      this._updateAttributes();

      const modelChanged = this.getModels()[0] !== oldModels[0];
      this._postUpdate(updateParams, modelChanged);
      // End subclass lifecycle methods
    } finally {
      // Restore shared context
      context.viewport = currentViewport;
      this.props = currentProps;
      this._clearChangeFlags();
      internalState.needsUpdate = false;
      internalState.preprojectionChanged = false;
      internalState.resetOldProps();
    }
  }
  /* eslint-enable max-statements */

  /** (Internal) Called by manager when layer is about to be disposed 
      Note: not guaranteed to be called on application shutdown */
  _finalize(): void {
    debug(TRACE_FINALIZE, this);

    // Call subclass lifecycle method
    this.finalizeState(this.context);
    // Finalize extensions
    for (const extension of this.props.extensions) {
      extension.finalizeState.call(this, this.context, extension);
    }
  }

  // Calculates uniforms
  _drawLayer({
    renderPass,
    shaderModuleProps = null,
    uniforms = {},
    parameters = {}
  }: {
    renderPass: RenderPass;
    shaderModuleProps: any;
    uniforms: any;
    parameters: LumaParameters;
  }): void {
    // SQL accessors can defer the first update that creates the layer models.
    if (this.props[ACCESSOR_QUERIES_SYMBOL] && !this.internalState?.propsInTransition) {
      return;
    }
    this._updateAttributeTransition();

    const currentProps = this.props;
    const context = this.context;
    // Overwrite this.props during redraw to use in-transition prop values
    // `internalState.propsInTransition` could be missing if `updateState` failed
    // @ts-ignore (TS2339) internalState is alwasy defined when this method is called
    this.props = this.internalState.propsInTransition || currentProps;

    try {
      // TODO/ib - hack move to luma Model.draw
      if (shaderModuleProps) {
        this.setShaderModuleProps(shaderModuleProps);
      }

      // Apply polygon offset to avoid z-fighting
      // TODO - move to draw-layers
      const {getPolygonOffset} = this.props;
      const offsets = (getPolygonOffset && getPolygonOffset(uniforms)) || [0, 0];

      if (context.device instanceof WebGLDevice) {
        context.device.setParametersWebGL({polygonOffset: offsets});
      }

      const webGPUDrawParameters =
        context.device instanceof WebGLDevice ? null : splitWebGPUDrawParameters(parameters);

      applyModelParameters(this.getModels(), parameters, webGPUDrawParameters, offsets);

      // Call subclass lifecycle method
      if (context.device instanceof WebGLDevice) {
        const {colorMask, ...webGLParameters} = parameters;
        if (typeof colorMask === 'number') {
          Object.assign(webGLParameters, {
            colorMask: [
              Boolean(colorMask & 1),
              Boolean(colorMask & 2),
              Boolean(colorMask & 4),
              Boolean(colorMask & 8)
            ]
          });
        } else if (colorMask) {
          Object.assign(webGLParameters, {colorMask});
        }
        context.device.withParametersWebGL(webGLParameters, () => {
          const opts: DrawOptions = {renderPass, shaderModuleProps, uniforms, parameters, context};

          // extensions
          for (const extension of this.props.extensions) {
            extension.draw.call(this, opts, extension);
          }

          this.draw(opts);
        });
      } else {
        const previousParameters = renderPass.getParameters();
        try {
          renderPass.setParameters(webGPUDrawParameters?.renderPassParameters || {});
          const opts: DrawOptions = {renderPass, shaderModuleProps, uniforms, parameters, context};

          for (const extension of this.props.extensions) {
            extension.draw.call(this, opts, extension);
          }

          this.draw(opts);
        } finally {
          renderPass.setParameters(previousParameters);
        }
      }
    } finally {
      this.props = currentProps;
    }

    // End lifecycle method
  }

  // Helper methods
  /** Returns the current change flags */
  getChangeFlags(): ChangeFlags | undefined {
    return this.internalState?.changeFlags;
  }

  /* eslint-disable complexity */
  /** Dirty some change flags, will be handled by updateLayer */
  setChangeFlags(flags: Partial<ChangeFlags>): void {
    if (!this.internalState) {
      return;
    }
    const {changeFlags} = this.internalState;

    /* eslint-disable no-fallthrough, max-depth */
    for (const key in flags) {
      if (flags[key]) {
        let flagChanged = false;
        switch (key) {
          case 'dataChanged':
            // changeFlags.dataChanged may be `false`, a string (reason) or an array of ranges
            const dataChangedReason = flags[key];
            const prevDataChangedReason = changeFlags[key];
            if (dataChangedReason && Array.isArray(prevDataChangedReason)) {
              // Merge partial updates
              changeFlags.dataChanged = Array.isArray(dataChangedReason)
                ? prevDataChangedReason.concat(dataChangedReason)
                : dataChangedReason;
              flagChanged = true;
            }

          default:
            if (!changeFlags[key]) {
              changeFlags[key] = flags[key];
              flagChanged = true;
            }
        }
        if (flagChanged) {
          debug(TRACE_CHANGE_FLAG, this, key, flags);
        }
      }
    }
    /* eslint-enable no-fallthrough, max-depth */

    // Update composite flags
    const propsOrDataChanged = Boolean(
      changeFlags.dataChanged ||
        changeFlags.updateTriggersChanged ||
        changeFlags.propsChanged ||
        changeFlags.extensionsChanged
    );
    changeFlags.propsOrDataChanged = propsOrDataChanged;
    changeFlags.somethingChanged =
      propsOrDataChanged ||
      changeFlags.viewportChanged ||
      changeFlags.projectionChanged ||
      changeFlags.stateChanged;
  }
  /* eslint-enable complexity */

  /** Clear all changeFlags, typically after an update */
  private _clearChangeFlags(): void {
    // @ts-ignore TS2531 this method can only be called internally with internalState assigned
    this.internalState.changeFlags = {
      dataChanged: false,
      propsChanged: false,
      updateTriggersChanged: false,
      viewportChanged: false,
      projectionChanged: false,
      stateChanged: false,
      extensionsChanged: false,
      propsOrDataChanged: false,
      somethingChanged: false
    };
  }

  /** Compares the layers props with old props from a matched older layer
      and extracts change flags that describe what has change so that state
      can be update correctly with minimal effort */
  private _diffProps(newProps: Layer<PropsT>['props'], oldProps: Layer<PropsT>['props']) {
    const changeFlags = {
      ...diffProps(newProps, oldProps),
      projectionChanged: !areCRSEqual(newProps.coordinateSystem, oldProps.coordinateSystem)
    };

    // iterate over changedTriggers
    if (changeFlags.updateTriggersChanged) {
      for (const key in changeFlags.updateTriggersChanged) {
        if (changeFlags.updateTriggersChanged[key]) {
          this.invalidateAttribute(key);
        }
      }
    }

    // trigger uniform transitions
    if (changeFlags.transitionsChanged) {
      for (const key in changeFlags.transitionsChanged) {
        // prop changed and transition is enabled
        // @ts-ignore (TS2531) internalState is always defined when this method is called
        this.internalState.uniformTransitions.add(
          key,
          this.getUniformTransitionValue(key, oldProps[key]),
          this.getUniformTransitionValue(key, newProps[key]),
          newProps.transitions?.[key]
        );
      }
    }

    return this.setChangeFlags(changeFlags);
  }

  /** (Internal) called by layer manager to perform extra props validation (in development only) */
  validateProps(): void {
    validateProps(this.props);
  }

  /** (Internal) Called by deck picker when the hovered object changes to update the auto highlight */
  updateAutoHighlight(info: PickingInfo): void {
    if (this.props.autoHighlight && !Number.isInteger(this.props.highlightedObjectIndex)) {
      this._updateAutoHighlight(info);
    }
  }

  // May be overriden by subclasses

  // TODO - simplify subclassing interface
  /** Update picking module parameters to highlight the hovered object */
  protected _updateAutoHighlight(info: PickingInfo): void {
    const picking: PickingProps = {
      // @ts-ignore
      highlightedObjectColor: info.picked ? info.color : null
    };
    const {highlightColor} = this.props;
    const state = this.internalState!;
    state.hoverHighlightInfo = info.picked ? {...info} : null;
    if (info.picked && typeof highlightColor === 'function') {
      const color = highlightColor(info);
      picking.highlightColor = color as PickingProps['highlightColor'];
      picking.normalizedHighlightColor = this.usesNormalizedColors() && Array.isArray(color);
    }
    this.setShaderModuleProps({picking});
    // setShaderModuleProps does not trigger redraw
    this.setNeedsRedraw();
  }

  /** Create new attribute manager */
  protected _getAttributeManager(): AttributeManager | null {
    const context = this.context;
    return new AttributeManager(context.device, {
      id: this.props.id,
      stats: context.stats,
      timeline: context.timeline
    });
  }

  // Private methods

  /** Called after updateState to perform common tasks */
  // eslint-disable-next-line complexity
  protected _postUpdate(updateParams: UpdateParameters<Layer<PropsT>>, forceUpdate: boolean) {
    const {props, oldProps, changeFlags} = updateParams;

    // Note: Automatic instance count update only works for single layers
    const model = this.state.model as LumaGPUVectorModel | undefined;
    if (model?.isInstanced) {
      model.setInstanceCount(this.getNumInstances());
    }

    // Set picking module parameters to match props
    const {autoHighlight, highlightedObjectIndex, highlightColor} = props;
    const state = this.internalState!;
    const normalizedHighlightColor = this.usesNormalizedColors();
    const colorConventionChanged = state.normalizedHighlightColor !== normalizedHighlightColor;
    state.normalizedHighlightColor = normalizedHighlightColor;
    const hoverDataChanged = Boolean(changeFlags.dataChanged && state.hoverHighlightInfo);
    if (
      forceUpdate ||
      !autoHighlight ||
      Number.isInteger(highlightedObjectIndex) ||
      hoverDataChanged
    ) {
      state.hoverHighlightInfo = null;
    }
    if (
      forceUpdate ||
      oldProps.autoHighlight !== autoHighlight ||
      oldProps.highlightedObjectIndex !== highlightedObjectIndex ||
      oldProps.highlightColor !== highlightColor ||
      colorConventionChanged ||
      hoverDataChanged
    ) {
      const picking: PickingProps = {};

      const hoverInfo = state.hoverHighlightInfo;
      const color =
        typeof highlightColor === 'function'
          ? hoverInfo &&
            highlightColor({
              ...hoverInfo,
              layer: hoverInfo.layer?.id === this.id ? this : hoverInfo.layer,
              sourceLayer: hoverInfo.sourceLayer?.id === this.id ? this : hoverInfo.sourceLayer
            })
          : Array.isArray(highlightColor) && highlightColor;
      if (color) {
        picking.highlightColor = color as PickingProps['highlightColor'];
        picking.normalizedHighlightColor =
          normalizedHighlightColor &&
          Array.isArray(color) &&
          (typeof highlightColor === 'function' || color !== DEFAULT_HIGHLIGHT_COLOR);
      }

      // highlightedObjectIndex will overwrite any settings from auto highlighting.
      // Do not reset unless the value has changed.
      if (
        forceUpdate ||
        oldProps.autoHighlight !== autoHighlight ||
        highlightedObjectIndex !== oldProps.highlightedObjectIndex ||
        hoverDataChanged
      ) {
        picking.highlightedObjectColor =
          Number.isFinite(highlightedObjectIndex) && (highlightedObjectIndex as number) >= 0
            ? this.encodePickingColor(highlightedObjectIndex)
            : null;
      }

      this.setShaderModuleProps({picking});
    }
  }

  private _getUpdateParams(): UpdateParameters<Layer<PropsT>> {
    return {
      props: this.props,
      // @ts-ignore TS2531 this method can only be called internally with internalState assigned
      oldProps: this.internalState.getOldProps() as PropsT,
      context: this.context,
      // @ts-ignore TS2531 this method can only be called internally with internalState assigned
      changeFlags: this.internalState.changeFlags
    };
  }

  /** Checks state of attributes and model */
  private _getNeedsRedraw(opts: {clearRedrawFlags: boolean}): string | false {
    // this method may be called by the render loop as soon a the layer
    // has been created, so guard against uninitialized state
    if (!this.internalState) {
      return false;
    }

    let redraw: string | false = false;
    redraw = redraw || (this.internalState.needsRedraw && this.id);

    // TODO - is attribute manager needed? - Model should be enough.
    const attributeManager = this.getAttributeManager();
    const attributeManagerNeedsRedraw = attributeManager
      ? attributeManager.getNeedsRedraw(opts)
      : false;
    redraw = redraw || attributeManagerNeedsRedraw;

    if (redraw) {
      for (const extension of this.props.extensions) {
        extension.onNeedsRedraw.call(this, extension);
      }
    }

    this.internalState.needsRedraw = this.internalState.needsRedraw && !opts.clearRedrawFlags;
    return redraw;
  }

  /** Callback when asyn prop is loaded */
  private _onAsyncPropUpdated(): void {
    // @ts-ignore TS2531 this method can only be called internally with internalState assigned
    this._diffProps(this.props, this.internalState.getOldProps());
    this.setNeedsUpdate();
  }
}

function splitWebGPUDrawParameters(parameters: LumaParameters): {
  pipelineParameters: LumaParameters;
  renderPassParameters?: {blendConstant: [number, number, number, number]};
} {
  const {blendConstant, ...pipelineParameters} = parameters as LumaParameters & {
    blendConstant?: [number, number, number, number];
  };

  return blendConstant
    ? {
        pipelineParameters,
        renderPassParameters: {blendConstant}
      }
    : {pipelineParameters};
}

function applyModelParameters(
  models: LumaGPUVectorModel[],
  parameters: LumaParameters,
  webGPUDrawParameters: ReturnType<typeof splitWebGPUDrawParameters> | null,
  polygonOffset: number[]
): void {
  for (const model of models) {
    if (model.device.type === 'webgpu') {
      // TODO(ibgreen): model.setParameters currently wipes parameters. Semantics TBD.
      model.setParameters({
        ...model.parameters,
        // WebGPU depth bias, like WebGL polygon offset, applies only to triangles.
        ...(model.topology.startsWith('triangle') && {
          depthBias: Math.round(polygonOffset[1]),
          depthBiasSlopeScale: polygonOffset[0]
        }),
        ...webGPUDrawParameters?.pipelineParameters
      });
    } else {
      model.setParameters(parameters);
    }
  }
}
// Resolve the current layer at invocation: layer instances are replaced while attributes survive.
function transformPosition(this: Layer, input: number[]): [number, number, number] {
  const position: [number, number, number] = [input[0], input[1], input[2] ?? 0];
  if (this.props.modelMatrix) {
    // Transform the local copy in place without allocating a matrix for each vertex.
    transformMat4(position, position, this.props.modelMatrix);
  }
  for (let axis = 0; axis < 3; axis++) position[axis] += this.props.coordinateOrigin[axis];
  return this.internalState!.preproject!(position);
}
