import type {Device, RenderPass} from '@luma.gl/core';
import {Timeline} from '@luma.gl/engine';
import type {ShaderAssembler, ShaderModule, ShaderPlugin} from '@luma.gl/shaders';
import {getShaderAssembler, layerUniforms} from '../shaderlib/index';
import {LIFECYCLE} from '../lifecycle/constants';
import log from '../utils/log';
import debug from '../debug/index';
import {flatten} from '../utils/flatten';
import {Stats} from 'probe.gl/stats';
import ResourceManager from './resource/resource-manager';
import ProjectionScaleResources from './projection-scale-resources';

import {resolveCRS, areCRSEqual} from '../utils/crs';
import type {CRSDescriptor, TypeScriptCRSInput} from '@math.gl/geospatial/projection-core';
import type Viewport from '../viewports/viewport';
import type View from '../views/view';

import type Layer from './layer';
import type CompositeLayer from './composite-layer';
import type Deck from './deck';

import type {SQLFunctions, SQLParser} from '../types/layer-props';

const TRACE_SET_LAYERS = 'layerManager.setLayers';
const TRACE_ACTIVATE_VIEWPORT = 'layerManager.activateViewport';

export type LayerContext = {
  layerManager: LayerManager;
  resourceManager: ResourceManager;
  deck?: Deck<any>;
  sqlParser?: SQLParser;
  /** Effective Deck color convention for participating layers. */
  normalizedColors?: boolean;
  /** Additional Arrow functions shared by all layer SQL accessors. */
  sqlFunctions?: SQLFunctions;
  device: Device;
  shaderAssembler: ShaderAssembler;
  defaultShaderModules: ShaderModule[];
  /** Effect plugins applied to all layer models alongside default shader modules. */
  defaultShaderPlugins: ShaderPlugin[];
  renderPass: RenderPass;
  stats: Stats;
  viewport: Viewport;
  timeline: Timeline;
  mousePosition: {x: number; y: number} | null;
  userData: any;
  onError?: <PropsT extends {}>(error: Error, source: Layer<PropsT>) => void;
  /** @deprecated Use context.device */
  gl: WebGL2RenderingContext;
};

export type LayersList = (Layer | undefined | false | null | LayersList)[];

export type LayerManagerProps = {
  deck?: Deck<any>;
  stats?: Stats;
  viewport?: Viewport | null;
  timeline?: Timeline;
};
export default class LayerManager {
  layers: Layer[];
  // Layer lifecycle callbacks receive a viewport; the manager may wait without one.
  context: Omit<LayerContext, 'viewport'> & {viewport: Viewport | null};
  resourceManager: ResourceManager;

  private _coordinateSystems = new Map<
    string,
    {
      coordinateSystem: TypeScriptCRSInput;
      layer: Layer;
      sourceCrs?: CRSDescriptor | null;
      pending?: Promise<CRSDescriptor>;
      error?: Error;
    }
  >();
  private _lastRenderedLayers: LayersList = [];
  private _viewports = new Map<string, Viewport | null>();
  private _layerFilter: Deck['props']['layerFilter'] = null;
  readonly projectionScaleResources: ProjectionScaleResources;
  private _needsRedraw: string | false = false;
  private _needsUpdate: string | false = false;
  private _nextLayers: LayersList | null = null;
  private _debug: boolean = false;
  // This flag is separate from _needsUpdate because it can be set during an update and should trigger another full update
  private _defaultShaderModulesChanged: boolean = false;

  /**
   * @param device
   * @param param1
   */
  // eslint-disable-next-line
  constructor(device: Device, props: LayerManagerProps) {
    const {deck, stats, viewport, timeline} = props || {};

    // Currently deck.gl expects the DeckGL.layers array to be different
    // whenever React rerenders. If the same layers array is used, the
    // LayerManager's diffing algorithm will generate a fatal error and
    // break the rendering.

    // `this._lastRenderedLayers` stores the UNFILTERED layers sent
    // down to LayerManager, so that `layers` reference can be compared.
    // If it's the same across two React render calls, the diffing logic
    // will be skipped.
    this.layers = [];
    this.resourceManager = new ResourceManager({device, protocol: 'deck://'});
    this.projectionScaleResources = new ProjectionScaleResources(device);

    this.context = {
      mousePosition: null,
      userData: {},
      layerManager: this,
      device,
      // @ts-expect-error
      gl: device?.gl,
      deck,
      shaderAssembler: getShaderAssembler(device?.info?.shadingLanguage || 'glsl'),
      defaultShaderModules: [layerUniforms],
      defaultShaderPlugins: [],
      renderPass: undefined!,
      stats: stats || new Stats({id: 'deck.gl'}),
      viewport: viewport || null,
      timeline: timeline || new Timeline(),
      resourceManager: this.resourceManager,
      onError: undefined
    };

    Object.seal(this);
  }

  /** Method to call when the layer manager is not needed anymore. */
  finalize() {
    this.projectionScaleResources.destroy();
    this.resourceManager.finalize();
    // Finalize all layers
    for (const layer of this.layers) {
      this._finalizeLayer(layer);
    }
    this._coordinateSystems.clear();
  }

  /** Check if a redraw is needed */
  needsRedraw(
    opts: {
      /** Reset redraw flags to false after the call */
      clearRedrawFlags: boolean;
    } = {clearRedrawFlags: false}
  ): string | false {
    let redraw = this._needsRedraw;
    if (opts.clearRedrawFlags) {
      this._needsRedraw = false;
    }

    // This layers list doesn't include sublayers, relying on composite layers
    for (const layer of this.layers) {
      // Call every layer to clear their flags
      const layerNeedsRedraw = layer.getNeedsRedraw(opts);
      redraw = redraw || layerNeedsRedraw;
    }

    return redraw;
  }

  /** Check if a deep update of all layers is needed */
  needsUpdate(): string | false {
    if (this._nextLayers && this._nextLayers !== this._lastRenderedLayers) {
      // New layers array may be the same as the old one if `setProps` is called by React
      return 'layers changed';
    }
    if (this._defaultShaderModulesChanged) {
      return 'shader modules changed';
    }
    return this._needsUpdate;
  }

  /** Layers will be redrawn (in next animation frame) */
  setNeedsRedraw(reason: string): void {
    this._needsRedraw = this._needsRedraw || reason;
  }

  /** Layers will be updated deeply (in next animation frame)
    Potentially regenerating attributes and sub layers */
  setNeedsUpdate(reason: string): void {
    this._needsUpdate = this._needsUpdate || reason;
  }

  /** Gets a list of currently rendered layers. Optionally filter by id. */
  getLayers({layerIds}: {layerIds?: string[]} = {}): Layer[] {
    // Filtering by layerId compares beginning of strings, so that sublayers will be included
    // Dependes on the convention of adding suffixes to the parent's layer name
    return layerIds
      ? this.layers.filter(layer => layerIds.find(layerId => layer.id.indexOf(layerId) === 0))
      : this.layers;
  }

  /** Set props needed for layer rendering and picking. */
  setProps(props: any): void {
    if ('layerFilter' in props && props.layerFilter !== this._layerFilter) {
      this._layerFilter = props.layerFilter;
      this.setNeedsUpdate('layerFilter changed');
    }
    if ('normalizedColors' in props && props.normalizedColors !== this.context.normalizedColors) {
      this.context.normalizedColors = props.normalizedColors;
      for (const layer of this.layers) {
        layer.setNeedsUpdate();
      }
      this.setNeedsUpdate('normalizedColors changed');
    }
    if ('sqlParser' in props && props.sqlParser !== this.context.sqlParser) {
      this.context.sqlParser = props.sqlParser;
      this.setNeedsUpdate('SQL parser changed');
    }
    if ('sqlFunctions' in props && props.sqlFunctions !== this.context.sqlFunctions) {
      this.context.sqlFunctions = props.sqlFunctions;
      this.setNeedsUpdate('SQL functions changed');
    }
    if ('debug' in props) {
      this._debug = props.debug;
    }

    // A way for apps to add data to context that can be accessed in layers
    if ('userData' in props) {
      this.context.userData = props.userData;
    }

    // New layers will be processed in `updateLayers` in the next update cycle
    if ('layers' in props) {
      this._nextLayers = props.layers;
    }

    if ('onError' in props) {
      this.context.onError = props.onError;
    }
  }

  /** Supply a new layer list, deferring matching and sublayer generation until a viewport exists. */
  setLayers(newLayers: LayersList, reason?: string): void {
    debug(TRACE_SET_LAYERS, this, reason, newLayers);

    if (!this.context.viewport) {
      // Keep the latest input and dirty flags until projection context is available.
      this._nextLayers = newLayers;
      this.setNeedsUpdate(reason || 'viewport pending');
      return;
    }

    this._nextLayers = null;
    this._lastRenderedLayers = newLayers;

    const flatLayers = flatten(newLayers, Boolean) as Layer[];

    for (const layer of flatLayers) {
      layer.context = this.context as LayerContext;
    }

    this._updateLayers(this.layers, flatLayers);
  }

  /** Update layers from last cycle if `setNeedsUpdate()` has been called */
  updateLayers(): void {
    if (!this.context.viewport) return;

    // NOTE: For now, even if only some layer has changed, we update all layers
    // to ensure that layer id maps etc remain consistent even if different
    // sublayers are rendered
    const reason = this.needsUpdate();
    if (reason) {
      this.setNeedsRedraw(`updating layers: ${reason}`);
      // Force a full update
      this.setLayers(this._nextLayers || this._lastRenderedLayers, reason);
    }
    // Updated, clear the backlog
    this._nextLayers = null;
  }

  //
  // INTERNAL METHODS
  //

  /**
   * Returns the complete active viewport set for layer traversal and consumer cleanup.
   * Includes views excluded by render-time layerFilter callbacks. Without a Deck,
   * returns the currently activated viewport.
   */
  getViewports(): Viewport[] {
    return (
      this.context.deck?.getViewports() || (this.context.viewport ? [this.context.viewport] : [])
    );
  }

  /** Refresh view availability without substituting another view for a pending CRS. */
  setViewports(viewports: Viewport[], views: View[]): void {
    this._viewports = new Map(views.map(view => [view.id, null]));
    for (const viewport of viewports) this._viewports.set(viewport.id, viewport);
    this.context.viewport = viewports[0] || null;
    for (const layer of this.layers) {
      const state = layer.internalState;
      if (!state?.viewport) continue;
      const viewport = this._viewports.get(state.viewport.id);
      if (viewport === null) continue;
      if (viewport !== state.viewport) {
        state.viewport = viewport;
        layer.setChangeFlags({viewportChanged: true});
      }
    }
    this.setNeedsUpdate('viewports changed');
  }

  /** Whether the layer's selected view has materialized its replacement viewport. */
  isViewportReady(layer: Layer): boolean {
    const viewport = layer.internalState?.viewport;
    return !viewport || this._viewports.get(viewport.id) !== null;
  }

  /** Set the current viewport, or suspend layer updates when none is available. */
  activateViewport = (viewport?: Viewport | null) => {
    debug(TRACE_ACTIVATE_VIEWPORT, this, viewport);
    const wasPending = !this.context.viewport;
    this.context.viewport = viewport || null;
    if (viewport && wasPending) {
      // A retained layer viewport belongs to the previous view. Resume against the
      // materialized viewport before any attribute or sublayer update can run.
      for (const layer of this.layers) {
        const internalState = layer.internalState;
        if (internalState && this.isViewportReady(layer)) {
          internalState.viewport = viewport;
          layer.setChangeFlags({
            viewportChanged: true
          });
        }
      }
      this.setNeedsUpdate('viewport available');
    }
  };

  /** Register a default shader module */
  addDefaultShaderModule(module: ShaderModule) {
    const {defaultShaderModules} = this.context;
    if (!defaultShaderModules.find(m => m.name === module.name)) {
      defaultShaderModules.push(module);
      this._defaultShaderModulesChanged = true;
    }
  }

  /** Deregister a default shader module */
  removeDefaultShaderModule(module: ShaderModule) {
    const {defaultShaderModules} = this.context;
    const i = defaultShaderModules.findIndex(m => m.name === module.name);
    if (i >= 0) {
      defaultShaderModules.splice(i, 1);
      this._defaultShaderModulesChanged = true;
    }
  }

  /** Register a default plugin and its uniform module for all layers. */
  addDefaultShaderPlugin(plugin: ShaderPlugin) {
    if (!this.context.defaultShaderPlugins.some(p => p.name === plugin.name)) {
      this.context.defaultShaderPlugins.push(plugin);
      if (plugin.module) this.addDefaultShaderModule(plugin.module);
      this._defaultShaderModulesChanged = true;
    }
  }

  /** Deregister a default plugin and rebuild layer models. */
  removeDefaultShaderPlugin(plugin: ShaderPlugin) {
    const index = this.context.defaultShaderPlugins.findIndex(p => p.name === plugin.name);
    if (index >= 0) {
      this.context.defaultShaderPlugins.splice(index, 1);
      if (plugin.module) this.removeDefaultShaderModule(plugin.module);
      this._defaultShaderModulesChanged = true;
    }
  }

  private _handleError(stage: string, error: Error, layer: Layer) {
    layer.raiseError(error, `${stage} of ${layer}`);
  }

  // TODO - mark layers with exceptions as bad and remove from rendering cycle?
  /** Match all layers, checking for caught errors
    to avoid having an exception in one layer disrupt other layers */
  private _updateLayers(oldLayers: Layer[], newLayers: Layer[]): void {
    // Create old layer map
    const oldLayerMap: {[layerId: string]: Layer | null} = {};
    for (const oldLayer of oldLayers) {
      if (oldLayerMap[oldLayer.id]) {
        log.warn(`Multiple old layers with same id ${oldLayer.id}`)();
      } else {
        oldLayerMap[oldLayer.id] = oldLayer;
      }
    }

    if (this._defaultShaderModulesChanged) {
      for (const layer of oldLayers) {
        layer.setNeedsUpdate();
        layer.setChangeFlags({extensionsChanged: true});
      }
      this._defaultShaderModulesChanged = false;
    }

    // Allocate array for generated layers
    const generatedLayers: Layer[] = [];

    // Match sublayers
    this._updateSublayersRecursively(newLayers, oldLayerMap, generatedLayers);

    // Finalize unmatched layers
    this._finalizeOldLayers(oldLayerMap);

    let needsUpdate: string | false = false;
    for (const layer of generatedLayers) {
      if (layer.hasUniformTransition()) {
        needsUpdate = `Uniform transition in ${layer}`;
        break;
      }
    }

    this._needsUpdate = needsUpdate;
    this.layers = generatedLayers;
  }

  /* eslint-disable complexity,max-statements */
  // Note: adds generated layers to `generatedLayers` array parameter
  private _updateSublayersRecursively(
    newLayers: Layer[],
    oldLayerMap: {[layerId: string]: Layer | null},
    generatedLayers: Layer[]
  ) {
    for (const newLayer of newLayers) {
      newLayer.context = this.context as LayerContext;

      // Given a new coming layer, find its matching old layer (if any)
      const oldLayer = oldLayerMap[newLayer.id];
      if (oldLayer === null) {
        // null, rather than undefined, means this id was originally there
        log.warn(`Multiple new layers with same id ${newLayer.id}`)();
      }
      // Remove the old layer from candidates, as it has been matched with this layer
      oldLayerMap[newLayer.id] = null;

      let sublayers: Layer[] | null = null;

      // We must not generate exceptions until after layer matching is complete
      try {
        if (this._debug && oldLayer !== newLayer) {
          newLayer.validateProps();
        }

        if (oldLayer?.internalState) this._transferLayerState(oldLayer, newLayer);
        const initialViewport = !newLayer.internalState
          ? this._getInitialViewport(newLayer)
          : undefined;
        const ready =
          this.isViewportReady(newLayer) && this._resolveLayerCrs(newLayer, initialViewport);
        if (ready) {
          if (!newLayer.internalState) {
            this._initializeLayer(newLayer, initialViewport);
          } else this._updateLayer(newLayer);
        }
        generatedLayers.push(newLayer);

        // Call layer lifecycle method: render sublayers
        sublayers =
          newLayer.internalState && newLayer.isComposite
            ? (newLayer as CompositeLayer).getSubLayers()
            : null;
        // End layer lifecycle method: render sublayers
      } catch (err) {
        this._handleError('matching', err as Error, newLayer); // Record first exception
      }

      if (sublayers) {
        this._updateSublayersRecursively(sublayers, oldLayerMap, generatedLayers);
      }
    }
  }
  /* eslint-enable complexity,max-statements */

  private _getInitialViewport(layer: Layer): Viewport | undefined {
    const viewports = this._viewports.size ? this._viewports.values() : [this.context.viewport];
    for (const viewport of viewports) {
      // Use the same root-layer filter as rendering, only to seed initialization.
      if (
        viewport &&
        (!this._layerFilter ||
          this._layerFilter({
            layer: layer.root,
            viewport,
            isPicking: false,
            renderPass: 'screen'
          }))
      )
        return viewport;
    }
    return undefined;
  }

  private _resolveLayerCrs(layer: Layer, initialViewport?: Viewport): boolean {
    const viewport = layer.internalState?.viewport || initialViewport || this.context.viewport!;
    const coordinateSystem =
      (layer.props.coordinateSystem ?? 'default') === 'default'
        ? viewport.isGeospatial
          ? 'WGS84'
          : 'cartesian'
        : layer.props.coordinateSystem;
    let entry = this._coordinateSystems.get(layer.id);
    if (!entry || !areCRSEqual(entry.coordinateSystem, coordinateSystem)) {
      entry = {coordinateSystem, layer};
      this._coordinateSystems.set(layer.id, entry);
      const resolved =
        coordinateSystem === viewport.crs?.signature ? viewport.crs! : resolveCRS(coordinateSystem);
      if (resolved instanceof Promise) {
        entry.pending = resolved;
        const request = entry;
        resolved.then(
          sourceCrs => {
            if (this._coordinateSystems.get(layer.id) !== request) return;
            request.sourceCrs = sourceCrs;
            request.pending = undefined;
            this.setNeedsUpdate('source CRS loaded');
          },
          error => {
            if (this._coordinateSystems.get(layer.id) !== request) return;
            request.error = error;
            request.pending = undefined;
            request.layer.raiseError(error, 'loading coordinateSystem');
          }
        );
      } else {
        entry.sourceCrs = resolved;
      }
    }
    entry.coordinateSystem = coordinateSystem;
    entry.layer = layer;
    layer._setSourceCrs(entry.pending || entry.error ? undefined : entry.sourceCrs);
    return !entry.pending && !entry.error;
  }

  // Finalize any old layers that were not matched
  private _finalizeOldLayers(oldLayerMap: {[layerId: string]: Layer | null}): void {
    for (const layerId in oldLayerMap) {
      const layer = oldLayerMap[layerId];
      if (layer) {
        this._finalizeLayer(layer);
      }
    }
  }

  // / EXCEPTION SAFE LAYER ACCESS

  /** Safely initializes a single layer, calling layer methods */
  private _initializeLayer(layer: Layer, initialViewport?: Viewport): void {
    try {
      layer._initialize(initialViewport);
      layer.lifecycle = LIFECYCLE.INITIALIZED;
    } catch (err) {
      this._handleError('initialization', err as Error, layer);
      // TODO - what should the lifecycle state be here? LIFECYCLE.INITIALIZATION_FAILED?
    }
  }

  /** Transfer state from one layer to a newer version */
  private _transferLayerState(oldLayer: Layer, newLayer: Layer): void {
    newLayer._transferState(oldLayer);
    newLayer.lifecycle = LIFECYCLE.MATCHED;

    if (newLayer !== oldLayer) {
      oldLayer.lifecycle = LIFECYCLE.AWAITING_GC;
    }
  }

  /** Safely updates a single layer, cleaning all flags */
  private _updateLayer(layer: Layer): void {
    try {
      layer._update();
    } catch (err) {
      this._handleError('update', err as Error, layer);
    }
  }

  /** Safely finalizes a single layer, removing all resources */
  private _finalizeLayer(layer: Layer): void {
    this._coordinateSystems.delete(layer.id);
    if (!layer.internalState) {
      layer.lifecycle = LIFECYCLE.FINALIZED;
      return;
    }
    this._needsRedraw = this._needsRedraw || `finalized ${layer}`;

    layer.lifecycle = LIFECYCLE.AWAITING_FINALIZATION;

    try {
      layer._finalize();
      layer.lifecycle = LIFECYCLE.FINALIZED;
    } catch (err) {
      this._handleError('finalization', err as Error, layer);
    }
  }
}
