import {packNormalizedColor} from '../utils/color';
import {createIterable} from '../utils/iterable-utils';
import {deepEqual} from '../utils/deep-equal';
import type {UpdateParameters} from './layer';
import {
  Buffer,
  dataTypeDecoder,
  type BufferLayout,
  type Device,
  type RenderPass,
  type VertexFormat
} from '@luma.gl/core';
import {DynamicBuffer} from '@luma.gl/core/dynamic';
import type {GPUVectorModel, GPUVectorModelInputs} from '@luma.gl/engine';
import {GPUConstant, GPUVector, getGPUVectorFormatInfo} from '@luma.gl/graph/gpu-data';

import type {PreparedArrowColumn} from '../arrow/append-arrow-column';
import {resolveColumns} from './resolve-columns';

export type ColumnDefinition = {
  attribute: string;
  accessor: string;
  semantic: 'position' | 'scalar' | 'color' | 'vector';
  size: number;
  prop?: boolean;
  /** Select an Arrow vector supplied through the matching accessor, after an explicit column. */
  arrowAccessor?: boolean;
  defaultValue?: number;
  /** Built-in byte color to preserve when normalizing plain-array input. */
  defaultColor?: readonly number[];
};

/** Definitions keyed by public column name, including internal inputs. */
export type ColumnDefinitions = Readonly<Record<string, Partial<ColumnDefinition>>>;

type PositionOptions = {
  transform?: ((value: number[]) => readonly number[]) | null;
  fp64?: boolean;
  requireRows?: boolean;
  onPosition?: (value: number[] | null) => void;
};

type Rows = {length: number; at(index: number): any};

type PrepareFallbacks = (
  rows: Rows,
  length: number,
  own: (resource: {destroy(): void}) => void
) => Record<string, unknown>;

type Request = {source: unknown; rows?: Rows; normalizedColors: boolean};

type Columns = Record<string, GPUVector | GPUConstant>;
type Prepared = {
  columns: Columns;
  /** Arrow source chunks and their conversion handles. */
  arrow?: Record<string, PreparedArrowColumn>;
  /** Allocations owned by this committed state; reused handles transfer on commit. */
  resources?: Set<{destroy(): void}>;
  /** Inputs used by the last successful conversion, including update triggers. */
  props?: Record<string, any>;
  /** Precision used for the committed position conversion. */
  fp64?: boolean;
  /** Whether committed positions required CPU preprojection. */
  transformed?: boolean;
  /** Invalidation generation satisfied by this conversion. */
  revision?: number;
  destroy(): void;
  length: number;
  source: unknown;
  rows: Rows;
  chunkLengths?: number[];
  bounds?: [number[], number[]];
};

/** Prepares column inputs and accessor fallbacks for a layer. */
export class LayerColumns {
  private prepared?: Prepared;
  private version = 0;
  /** Retains projection/trigger invalidation across superseded or failed requests. */
  private conversionRevision = 0;
  private request?: Request;
  loading = false;
  /** Number of rows in the last successfully prepared columns, used as the instance count. */
  get length(): number {
    return this.prepared?.length ?? 0;
  }
  /** Returns source-coordinate position bounds for view fitting, including accessor fallbacks. */
  getBounds(): [number[], number[]] | null {
    return this.prepared?.bounds ?? null;
  }
  /** Identifies the picking input in the currently prepared columns. */
  get hasRowIndexes(): boolean {
    return Boolean(this.prepared?.columns.rowIndexes);
  }
  /** Uses the layer's device to upload accessor values and convert Arrow columns. */
  constructor(
    private readonly device: Device,
    private readonly definitions: Record<string, ColumnDefinition>,
    private readonly name: string,
    private readonly useRowIndexes = false,
    private readonly useTable = false
  ) {}

  /** Supplies shader input layouts while asynchronous conversion has not produced buffers yet. */
  getBufferLayouts(useRowIndexes = false): BufferLayout[] {
    const formats: Record<string, VertexFormat> = {};
    for (const definition of Object.values(this.definitions)) {
      formats[definition.attribute] = (
        definition.semantic === 'color'
          ? 'unorm8x4'
          : definition.size === 1
            ? 'float32'
            : `float32x${definition.size}`
      ) as VertexFormat;
      if (definition.semantic === 'position') formats[`${definition.attribute}64Low`] = 'float32x3';
    }
    if (useRowIndexes) formats.rowIndexes = 'uint32';
    let offset = 0;
    const attributes = Object.entries(formats).map(([name, format]) => {
      const attribute = {attribute: name, format, byteOffset: offset};
      offset += getGPUVectorFormatInfo(format).byteLength;
      return attribute;
    });
    return [{name: `${this.name}-initial`, stepMode: 'instance', byteStride: 0, attributes}];
  }

  /** Checks only column/accessor inputs; uniform-only changes do not upload columns again. */
  needsUpdate(props: Record<string, any>, oldProps: Record<string, any>): boolean {
    return (
      !this.request ||
      props.data !== this.request.source ||
      props._dataLoadOptions !== oldProps._dataLoadOptions ||
      !deepEqual(props.modelMatrix, oldProps.modelMatrix, 1) ||
      props.colorFormat !== oldProps.colorFormat ||
      !deepEqual(props.coordinateOrigin, oldProps.coordinateOrigin, 1) ||
      props.coordinateSystem !== oldProps.coordinateSystem ||
      Object.entries(this.definitions).some(
        ([name, definition]) =>
          props[name] !== oldProps[name] ||
          props[definition.accessor] !== oldProps[definition.accessor]
      )
    );
  }

  /** Starts conversion only when data, projection, or column inputs change. */
  updateIfNeeded(
    {
      props,
      oldProps,
      changeFlags
    }: Pick<UpdateParameters<any>, 'props' | 'oldProps'> & {
      changeFlags: Partial<
        Pick<
          UpdateParameters<any>['changeFlags'],
          'dataChanged' | 'updateTriggersChanged' | 'projectionChanged'
        >
      >;
    },
    {
      dataLoading,
      changed,
      failed,
      positionOptions,
      prepareFallbacks,
      normalizedColors = false
    }: {
      dataLoading: boolean;
      changed: () => void;
      failed: (error: Error) => void;
      positionOptions?: PositionOptions;
      prepareFallbacks?: PrepareFallbacks;
      normalizedColors?: boolean;
    }
  ): Promise<void> | undefined {
    if (
      !dataLoading &&
      (changeFlags.dataChanged ||
        changeFlags.updateTriggersChanged ||
        changeFlags.projectionChanged ||
        this.request?.normalizedColors !== normalizedColors ||
        this.needsUpdate(props, oldProps))
    ) {
      return this.update(
        props,
        changed,
        failed,
        positionOptions,
        prepareFallbacks,
        !changeFlags.projectionChanged && !changeFlags.updateTriggersChanged,
        normalizedColors
      );
    }
    return undefined;
  }

  /**
   * Converts explicit columns and fills missing inputs from accessors or binary attributes.
   * Replaces the previous result only after all inputs succeed; superseded requests release
   * their allocations so asynchronous completions cannot overwrite newer state. Unchanged Arrow
   * chunks retain their allocations unless snapshot mode or conversion invalidation disables reuse.
   */
  async update(
    props: Record<string, any>,
    changed: () => void,
    failed: (error: Error) => void,
    positionOptions: PositionOptions = {},
    prepareFallbacks?: PrepareFallbacks,
    reuseChunks = true,
    normalizedColors = false
  ): Promise<void> {
    const version = ++this.version;
    if (!reuseChunks) this.conversionRevision++;
    const revision = this.conversionRevision;
    this.loading = true;
    const previousRequest = this.request;
    const request: Request = {source: props.data, normalizedColors};
    this.request = request;
    const results: Array<{destroy(): void}> = [];
    try {
      const rows = this.getRows(props.data, previousRequest);
      request.rows = rows;
      if (version !== this.version) return;
      if (positionOptions.requireRows && !rows.length) {
        this.prepared?.destroy();
        this.prepared = {columns: {}, length: 0, source: props.data, rows, destroy() {}};
        this.loading = false;
        changed();
        return;
      }
      const {ArrowConverter} = await import('../arrow/upstream-luma/arrow-converter');
      const {appendArrowColumn} = await import('../arrow/append-arrow-column');
      const converter = new ArrowConverter(this.device);
      const previous = this.prepared;
      const reuse =
        previous?.revision === revision &&
        deepEqual(props.updateTriggers, previous.props?.updateTriggers, 2) &&
        reuseChunks &&
        props._dataLoadOptions !== 'snapshots' &&
        !positionOptions.transform &&
        !previous?.transformed &&
        previous?.fp64 === positionOptions.fp64 &&
        previous?.props &&
        ['modelMatrix', 'coordinateOrigin', 'coordinateSystem', 'colorFormat'].every(key =>
          deepEqual(props[key], previous.props![key], 1)
        );
      const arrow: Record<string, PreparedArrowColumn> = {};
      const retained = new Set<{destroy(): void}>();
      const columns: Columns = {};
      let bounds: [number[], number[]] | undefined;
      let boundsAvailable = true;
      positionOptions = {
        ...positionOptions,
        onPosition: value => {
          if (!value) {
            boundsAvailable = false;
            return;
          }
          bounds ??= [
            [Infinity, Infinity, Infinity],
            [-Infinity, -Infinity, -Infinity]
          ];
          for (let component = 0; component < 3; component++) {
            const coordinate = value[component] ?? 0;
            bounds[0][component] = Math.min(bounds[0][component], coordinate);
            bounds[1][component] = Math.max(bounds[1][component], coordinate);
          }
        }
      };
      const sources = resolveColumns(props, this.definitions, this.useTable);
      let length: number | undefined;
      let chunkLengths: number[] | undefined;
      for (const [name, definition] of Object.entries(this.definitions)) {
        const source = sources[name];
        if (!source) continue;
        if (source instanceof GPUVector) {
          const format =
            definition.semantic === 'color'
              ? 'unorm8x4'
              : definition.size === 1
                ? 'float32'
                : 'float32x' + definition.size;
          if (source.format !== format)
            throw new Error('GPU column format must match the shader input');
          if (definition.semantic === 'position') {
            if (positionOptions.transform)
              throw new Error('GPU positions cannot be CPU-preprojected');
            boundsAvailable = false;
          }
        }
        const result =
          source instanceof GPUVector
            ? {vector: source, residualVector: undefined, destroy() {}}
            : await appendArrowColumn(
                converter,
                source as Parameters<typeof converter.convert>[0],
                {
                  name,
                  semantic: definition.semantic === 'vector' ? 'numeric' : definition.semantic,
                  ...(definition.semantic === 'position'
                    ? {
                        format: 'float32x3',
                        transform: positionOptions.transform ?? undefined,
                        fp64: positionOptions.fp64
                      }
                    : {})
                },
                resource => results.push(resource),
                reuse ? previous?.arrow?.[name] : undefined
              );
        if (!(source instanceof GPUVector)) {
          const prepared = result as PreparedArrowColumn;
          arrow[name] = prepared;
          for (const resource of prepared.resources) {
            if (previous?.resources?.has(resource)) retained.add(resource);
          }
          if (prepared.bounds) {
            positionOptions.onPosition!(prepared.bounds[0]);
            positionOptions.onPosition!(prepared.bounds[1]);
          }
        }
        if (version !== this.version) {
          for (const result of results) result.destroy();
          return;
        }
        const lengths = result.vector.data.map(chunk => chunk.length);
        if (
          chunkLengths &&
          (lengths.length !== chunkLengths.length ||
            lengths.some((value, index) => value !== chunkLengths![index]))
        )
          throw new Error('Arrow column chunk structures must match');
        chunkLengths ??= lengths;
        length ??= result.vector.length;
        if (result.vector.length !== length) throw new Error('Arrow column lengths must match');
        columns[definition.attribute] = result.vector;
        if (definition.semantic === 'position' && result.residualVector)
          columns[`${definition.attribute}64Low`] = result.residualVector;
      }
      length ??= rows.length;
      chunkLengths ??= [length];
      if (rows.length && rows.length !== length)
        throw new Error('data rows must match Arrow column lengths');
      const fallbacks = prepareFallbacks?.(rows, length, resource => results.push(resource));
      for (const [name, definition] of Object.entries(this.definitions)) {
        if (!sources[name]) {
          columns[definition.attribute] = await this.makeAccessorColumn(
            props,
            definition.accessor,
            definition.size,
            definition.semantic === 'color',
            length,
            results,
            columns,
            positionOptions,
            rows,
            definition.semantic === 'position' ? `${definition.attribute}64Low` : undefined,
            definition.defaultValue,
            fallbacks?.[definition.accessor],
            definition.attribute,
            normalizedColors ? definition.defaultColor : undefined
          );
        }
      }
      if (this.useRowIndexes && props.data?.attributes?.rowIndexes) {
        columns.rowIndexes = await this.makeAccessorColumn(
          props,
          'rowIndexes',
          1,
          false,
          length,
          results,
          columns,
          positionOptions,
          rows
        );
      }
      for (const definition of Object.values(this.definitions)) {
        if (definition.semantic === 'position')
          columns[`${definition.attribute}64Low`] ??= new GPUConstant({
            format: 'float32x3',
            value: new Float32Array(3)
          });
      }
      if (this.device.type === 'webgpu') {
        const values = Object.values(columns);
        const bindingCount =
          values.filter(column => column instanceof GPUVector).length +
          Number(values.some(column => column instanceof GPUConstant));
        if (bindingCount > this.device.limits.maxVertexBuffers) {
          throw new Error(
            `${this.name} Arrow columns require ${bindingCount} vertex buffers; this device supports ${this.device.limits.maxVertexBuffers}`
          );
        }
      }
      if (version !== this.version) {
        for (const result of results) result.destroy();
        return;
      }
      for (const resource of retained) previous?.resources?.delete(resource);
      this.prepared?.destroy();
      const resources = new Set([...results, ...retained]);
      this.prepared = {
        columns,
        arrow,
        resources,
        props,
        fp64: positionOptions.fp64,
        transformed: Boolean(positionOptions.transform),
        revision,
        length,
        chunkLengths,
        bounds: length && boundsAvailable ? bounds : undefined,
        source: props.data,
        rows,
        destroy: () => {
          for (const resource of resources) resource.destroy();
          resources.clear();
        }
      };
      this.loading = false;
      changed();
    } catch (error) {
      for (const result of results) result.destroy();
      if (version === this.version) {
        this.loading = false;
        failed(error as Error);
        changed();
      }
    }
  }

  /** Draws matching batches using luma's managed uniform ranges and constant bindings. */
  draw(
    model: GPUVectorModel,
    renderPass: RenderPass,
    onBatch?: (offset: number, rowCount: number) => void
  ): void {
    const prepared = this.prepared;
    if (!prepared?.length) return;
    const vectors: GPUVectorModelInputs = {};
    const constants: Record<string, GPUConstant> = {};
    const layouts: BufferLayout[] = [];
    for (const [name, column] of Object.entries(prepared.columns)) {
      if (column instanceof GPUConstant) {
        constants[name] = column;
        continue;
      }
      // Accessor fallback buffers are contiguous. Borrow ranges matching the already
      // validated Arrow chunks, without copying or relaxing the column length contract.
      let start = 0;
      const data = (prepared.chunkLengths ?? [])
        .filter(length => length > 0)
        .map(length => {
          let chunkStart = 0;
          const chunk = column.data.find(candidate => {
            if (start < chunkStart + candidate.length) return true;
            chunkStart += candidate.length;
            return false;
          })!;
          const byteOffset = chunk.byteOffset + (start - chunkStart) * chunk.byteStride;
          start += length;
          return {
            buffer: chunk.buffer instanceof DynamicBuffer ? chunk.buffer.buffer : chunk.buffer,
            byteOffset,
            length,
            format: column.format,
            byteStride: chunk.byteStride,
            rowByteLength: chunk.rowByteLength
          };
        });
      vectors[name] = {
        name,
        format: column.format,
        length: column.length,
        byteStride: column.byteStride,
        rowByteLength: column.rowByteLength,
        data
      };
      // drawBatches binds each vector separately; constants are inferred and packed by luma.
      layouts.push({
        name,
        stepMode: 'instance',
        byteStride: column.byteStride,
        attributes: [{attribute: name, format: column.format as VertexFormat, byteOffset: 0}]
      });
    }
    model.setAttributeVectors({...vectors, ...constants}, layouts);
    model.drawBatches(renderPass, {
      vectors,
      onBatch: batch => onBatch?.(batch.rowIndexOffset, batch.rowCount)
    });
  }

  /** Releases owned conversion results and prevents completion of pending replacements. */
  destroy(): void {
    this.version++;
    this.prepared?.destroy();
    this.prepared = undefined;
    this.request = undefined;
  }

  /**
   * Provides indexed rows for fallback accessors without copying already indexable data.
   * Materializes iterables and retains one-shot iterator rows across pending or failed requests.
   */
  private getRows(data: any, previousRequest?: Request): Rows {
    if (data && Number.isFinite(data.length))
      return {length: data.length, at: index => data[index]};
    if (data && Number.isFinite(data.numRows) && typeof data.get === 'function') {
      return {length: data.numRows, at: index => data.get(index)};
    }
    const iterator = data?.[Symbol.iterator]?.();
    if (!iterator) return {length: 0, at: () => null};
    // Normalize a one-shot input once, even while its request is pending or failed.
    if (iterator === data) {
      if (previousRequest && previousRequest.source === data) {
        if (previousRequest.rows) return previousRequest.rows;
        throw new Error('Replace a failed row iterator before retrying');
      }
      if (this.prepared && this.prepared.source === data) return this.prepared.rows;
    }
    const rows = Array.from({[Symbol.iterator]: () => iterator});
    return {length: rows.length, at: index => rows[index]};
  }

  /**
   * Builds a missing shader input from a binary attribute, constant, or row accessor.
   * Borrows compatible buffers; otherwise packs and owns uploads, including position residuals
   * and coordinate transforms needed to match the normal attribute path.
   */
  private async makeAccessorColumn(
    props: Record<string, any>,
    accessor: string,
    size: number,
    color: boolean,
    length: number,
    owned: Array<{destroy(): void}>,
    columns: Columns,
    positionOptions: PositionOptions,
    rows: Rows,
    lowAttribute?: string,
    defaultValue = 0,
    binaryOverride?: unknown,
    attribute?: string,
    defaultColor?: readonly number[]
  ): Promise<GPUVector | GPUConstant> {
    let binaryColor = false;
    const binary =
      binaryOverride ??
      props.data?.attributes?.[accessor] ??
      (attribute && props.data?.attributes?.[attribute]);
    if (binary) {
      const descriptor = ArrayBuffer.isView(binary)
        ? {value: binary}
        : binary instanceof Buffer
          ? {buffer: binary}
          : binary;
      const values = descriptor.value;
      const sourceSize = descriptor.size ?? (color ? props.colorFormat?.length : undefined) ?? size;
      let type =
        descriptor.type ??
        (values instanceof Float64Array
          ? 'float64'
          : values
            ? dataTypeDecoder.getDataType(values)
            : accessor === 'rowIndexes'
              ? 'uint32'
              : color
                ? 'unorm8'
                : 'float32');
      if (!descriptor.type && (descriptor.normalized ?? color) && type !== 'float64')
        type = type.replace('int', 'norm');
      const typeInfo = type === 'float64' ? null : dataTypeDecoder.getDataTypeInfo(type);
      if (
        !descriptor.constant &&
        sourceSize === size &&
        type !== 'float64' &&
        (!typeInfo!.integer || accessor === 'rowIndexes') &&
        !(Boolean(lowAttribute) && (positionOptions.transform || values))
      ) {
        const format = (size === 1 ? type : `${type}x${size}`) as any;
        const bytes = getGPUVectorFormatInfo(format).byteLength;
        const buffer =
          descriptor.buffer ??
          this.device.createBuffer({
            data: values,
            usage: Buffer.VERTEX | Buffer.COPY_SRC | Buffer.COPY_DST
          });
        if (!descriptor.buffer) owned.push(buffer);
        if (
          length &&
          (descriptor.offset ?? 0) + (length - 1) * (descriptor.stride ?? bytes) + bytes >
            buffer.byteLength
        )
          throw new Error('Binary attribute is shorter than the Arrow columns');
        // GPU-only positions can be borrowed without requiring COPY_SRC/readback.
        if (lowAttribute) positionOptions.onPosition?.(null);
        return new GPUVector({
          type: 'buffer',
          name: accessor,
          buffer,
          ownsBuffer: false,
          format,
          length,
          byteOffset: descriptor.offset ?? 0,
          rowByteLength: bytes,
          byteStride: descriptor.stride ?? bytes
        });
      }
      const TypedArray =
        type === 'float64' ? Float64Array : dataTypeDecoder.getTypedArrayConstructor(type);
      const bytes = values ?? (await descriptor.buffer.readAsync());
      const view =
        values ??
        new TypedArray(
          bytes.buffer,
          bytes.byteOffset,
          bytes.byteLength / TypedArray.BYTES_PER_ELEMENT
        );
      const stride =
        (descriptor.stride ?? sourceSize * view.BYTES_PER_ELEMENT) / view.BYTES_PER_ELEMENT;
      const offset = (descriptor.offset ?? 0) / view.BYTES_PER_ELEMENT;
      const rowCount = descriptor.constant ? 1 : length;
      if (rowCount && offset + (rowCount - 1) * stride + sourceSize > view.length)
        throw new Error('Binary attribute is shorter than the Arrow columns');
      binaryColor = color;
      const normalize = (value: number) => {
        if (!typeInfo?.normalized) return value;
        const bits = typeInfo.byteLength * 8;
        return typeInfo.signed
          ? Math.max(-1, value / (2 ** (bits - 1) - 1))
          : value / (2 ** bits - 1);
      };
      const readValue = (index: number) =>
        sourceSize === 1
          ? normalize(view[offset + index * stride])
          : Array.from(
              view.subarray(offset + index * stride, offset + index * stride + sourceSize),
              normalize
            );
      props = {
        ...props,
        [accessor]: descriptor.constant ? readValue(0) : (_row, {index}) => readValue(index)
      };
    }
    const source = props[accessor];
    const format =
      accessor === 'rowIndexes'
        ? 'uint32'
        : color && !binaryColor
          ? 'unorm8x4'
          : size === 1
            ? 'float32'
            : `float32x${size}`;
    const lows =
      Boolean(lowAttribute) && positionOptions.fp64
        ? new Float32Array(Math.max(1, length) * size)
        : undefined;
    const pack = (
      value: any,
      target: Float32Array | Uint8Array | Uint8ClampedArray | Uint32Array,
      offset: number
    ) => {
      if (lowAttribute) positionOptions.onPosition?.(value);
      if (Boolean(lowAttribute) && positionOptions.transform)
        value = positionOptions.transform(value);
      if (size === 1) {
        const scalar = Number.isFinite(value) ? value : value?.[0];
        target[offset] = Number.isFinite(scalar) ? scalar : defaultValue;
        return;
      }
      if (
        defaultColor &&
        !binaryColor &&
        Array.isArray(value) &&
        (typeof source === 'function' || value !== defaultColor)
      ) {
        packNormalizedColor(value, target, offset, props.colorFormat === 'RGB' ? 3 : size);
        if (props.colorFormat === 'RGB') target[offset + 3] = 255;
        return;
      }
      for (let component = 0; component < size; component++) {
        target[offset + component] =
          color && !binaryColor && component === 3 && props.colorFormat === 'RGB'
            ? 255
            : (value?.[component] ?? (color && component === 3 ? (binaryColor ? 1 : 255) : 0));
        if (lows) lows[offset + component] = (value?.[component] ?? 0) - target[offset + component];
      }
    };
    if (typeof source !== 'function') {
      const value =
        accessor === 'rowIndexes'
          ? new Uint32Array(size)
          : color && !binaryColor
            ? new Uint8ClampedArray(size)
            : new Float32Array(size);
      pack(source, value, 0);
      if (lows)
        columns[lowAttribute!] = new GPUConstant({
          format: 'float32x3',
          value: lows.slice(0, size)
        });
      return new GPUConstant({
        format: format as any,
        value: value instanceof Uint8ClampedArray ? new Uint8Array(value.buffer) : value
      });
    }
    const values =
      accessor === 'rowIndexes'
        ? new Uint32Array(length * size)
        : color && !binaryColor
          ? new Uint8ClampedArray(length * size)
          : new Float32Array(length * size);
    const {objectInfo} = createIterable(null);
    objectInfo.data = props.data;
    for (let index = 0; index < length; index++) {
      objectInfo.index = index;
      pack(source(rows.at(index) ?? null, objectInfo), values, index * size);
    }
    const upload = (data: Float32Array | Uint8Array | Uint8ClampedArray | Uint32Array) => {
      const buffer = this.device.createBuffer({
        data,
        usage: Buffer.VERTEX | Buffer.COPY_DST | Buffer.COPY_SRC
      });
      owned.push(buffer);
      return new GPUVector({
        type: 'buffer',
        name: accessor,
        buffer,
        ownsBuffer: false,
        format: format as any,
        length
      });
    };
    if (lows) columns[lowAttribute!] = upload(lows);
    return upload(values);
  }
}
