/* eslint-disable complexity */
import DataColumn, {
  DataColumnOptions,
  ShaderAttributeOptions,
  BufferAccessor,
  DataColumnSettings
} from './data-column';
import {packNormalizedColor} from '../../utils/color';
import assert from '../../utils/assert';
import {createIterable, getAccessorFromBuffer} from '../../utils/iterable-utils';
import {fillArray} from '../../utils/flatten';
import {toDoublePrecisionArray} from '../../utils/math-utils';
import * as range from '../../utils/range';
import {bufferLayoutEqual} from './gl-utils';
import {normalizeTransitionSettings, TransitionSettings} from './transition-settings';
import {Buffer, getTypedArrayFromDataType} from '@luma.gl/core';
import type {Device, BufferLayout} from '@luma.gl/core';
import {
  GPUConstant,
  GPUVector,
  getGPUVectorData,
  getGPUVectorFormatInfo
} from '@luma.gl/graph/gpu-data';

import type {NumericArray, TypedArray} from '../../types/types';

/** Scratch color components consumed synchronously by attribute writes. */
const COLOR_SCRATCH: number[] = [];

export type Accessor<DataType, ReturnType> = (
  object: DataType,
  context: {
    data: any;
    index: number;
    target: number[];
  }
) => ReturnType;

export type Updater = (
  attribute: Attribute,
  {
    data,
    startRow,
    endRow,
    props,
    numInstances
  }: {
    data: any;
    startRow: number;
    endRow: number;
    props: any;
    numInstances: number;
  }
) => void;

export type AttributeOptions = DataColumnOptions<{
  transition?: boolean | Partial<TransitionSettings>;
  stepMode?: 'vertex' | 'instance' | 'dynamic';
  noAlloc?: boolean;
  /**
   * @internal
   * WebGPU-only hint to publish compatible CPU-backed attributes through one shared vertex
   * buffer. WebGL and unsupported grouped states retain the legacy standalone buffer path.
   */
  bufferGroup?: string;
  update?: Updater;
  accessor?: Accessor<any, any> | string | string[];
  /** @internal Identifies RGB(A) byte color accessors independently of their vertex format. */
  semanticType?: 'color';
  /** @internal Interpret plain-array color accessor inputs as normalized values. */
  normalizedColorInput?: boolean;
  /** Callback to map `accessor`'s return value to the attribute value. */
  transform?: ((value: any) => any) | null;
  /** Identifies the transform dependency; `projection` enables automatic position invalidation. */
  transformSource?: string;
  shaderAttributes?: Record<string, Partial<ShaderAttributeOptions>>;
}>;

export type BinaryAttribute = Partial<BufferAccessor> & {value?: TypedArray; buffer?: Buffer};

type AttributeInternalState = {
  startIndices: NumericArray | null;
  /** One unnormalized row retained for WebGPU buffer-group interleaving. */
  constantValue: TypedArray | null;
  /** Legacy: external binary supplied via attribute name */
  lastExternalBuffer: TypedArray | Buffer | BinaryAttribute | null;
  /** External binary supplied via accessor name */
  binaryValue: TypedArray | Buffer | BinaryAttribute | GPUVector | null;
  binaryAccessor: Accessor<any, any> | null;
  needsUpdate: string | boolean;
  needsRedraw: string | boolean;
  layoutChanged: boolean;
  updateRanges: number[][];
};

export default class Attribute extends DataColumn<AttributeOptions, AttributeInternalState> {
  /** Legacy approach to set attribute value - read `isConstant` instead for attribute state */
  constant: boolean = false;

  constructor(device: Device, opts: AttributeOptions) {
    // Constant and row accessors both use DataColumn's component writer and defaults.
    const options =
      opts.semanticType === 'color'
        ? {...opts, normalizedColorInput: false, defaultValue: opts.defaultValue ?? [0, 0, 0, 255]}
        : opts;
    super(device, options, {
      startIndices: null,
      constantValue: null,
      lastExternalBuffer: null,
      binaryValue: null,
      binaryAccessor: null,
      needsUpdate: true,
      needsRedraw: false,
      layoutChanged: false,
      updateRanges: range.FULL
    });

    // eslint-disable-next-line
    this.settings.update = opts.update || (opts.accessor ? this._autoUpdater : undefined);

    Object.seal(this.settings);
    Object.seal(this.state);

    // Check all fields and generate helpful error messages
    this._validateAttributeUpdaters();
  }

  get startIndices(): NumericArray | null {
    return this.state.startIndices;
  }

  set startIndices(layout: NumericArray | null) {
    this.state.startIndices = layout;
  }

  needsUpdate(): string | boolean {
    return this.state.needsUpdate;
  }

  needsRedraw({clearChangedFlags = false}: {clearChangedFlags?: boolean} = {}): string | boolean {
    const needsRedraw = this.state.needsRedraw;
    this.state.needsRedraw = needsRedraw && !clearChangedFlags;
    return needsRedraw;
  }

  layoutChanged(): boolean {
    return this.state.layoutChanged;
  }

  /** Requests a new model buffer layout, e.g. when this attribute replaces a transition buffer */
  setLayoutChanged(): void {
    this.state.layoutChanged = true;
  }

  setAccessor(accessor: DataColumnSettings<AttributeOptions>) {
    this.state.layoutChanged ||= !bufferLayoutEqual(accessor, this.getAccessor());
    super.setAccessor(accessor);
  }

  getUpdateTriggers(): string[] {
    const {accessor} = this.settings;

    // Backards compatibility: allow attribute name to be used as update trigger key
    return [this.id].concat((typeof accessor !== 'function' && accessor) || []);
  }

  supportsTransition(): boolean {
    return Boolean(this.settings.transition);
  }

  // Resolve transition settings object if transition is enabled, otherwise `null`
  getTransitionSetting(opts: Record<string, any>): TransitionSettings | null {
    if (!opts || !this.supportsTransition()) {
      return null;
    }
    const {accessor} = this.settings;
    // TODO: have the layer resolve these transition settings itself?
    const layerSettings = this.settings.transition;
    // these are the transition settings passed in by the user
    const userSettings = Array.isArray(accessor)
      ? // @ts-ignore
        opts[accessor.find(a => opts[a])]
      : // @ts-ignore
        opts[accessor];

    // Shorthand: use duration instead of parameter object
    return normalizeTransitionSettings(userSettings, layerSettings);
  }

  setNeedsUpdate(reason: string = this.id, dataRange?: {startRow?: number; endRow?: number}): void {
    this.state.needsUpdate = this.state.needsUpdate || reason;
    this.setNeedsRedraw(reason);
    if (dataRange) {
      const {startRow = 0, endRow = Infinity} = dataRange;
      this.state.updateRanges = range.add(this.state.updateRanges, [startRow, endRow]);
    } else {
      this.state.updateRanges = range.FULL;
    }
  }

  clearNeedsUpdate(): void {
    this.state.needsUpdate = false;
    this.state.updateRanges = range.EMPTY;
  }

  setNeedsRedraw(reason: string = this.id): void {
    this.state.needsRedraw = this.state.needsRedraw || reason;
  }

  allocate(numInstances: number): boolean {
    const {state, settings} = this;

    if (settings.noAlloc) {
      // Data is provided through a Buffer object.
      return false;
    }

    if (settings.update) {
      const wasConstant = this.isConstant;
      super.allocate(numInstances, state.updateRanges !== range.FULL);
      state.layoutChanged ||= wasConstant && this.device.type === 'webgpu';
      return true;
    }

    return false;
  }

  updateBuffer({
    numInstances,
    data,
    props,
    context
  }: {
    numInstances: number;
    data: any;
    props: any;
    context: any;
  }): boolean {
    if (!this.needsUpdate()) {
      return false;
    }

    const {
      state: {updateRanges},
      settings: {update, noAlloc}
    } = this;

    let updated = true;
    if (update) {
      // Custom updater - typically for non-instanced layers
      for (const [startRow, endRow] of updateRanges) {
        update.call(context, this, {data, startRow, endRow, props, numInstances});
      }
      if (!this.value) {
        // no value was assigned during update
      } else if (
        this.constant ||
        !this.buffer ||
        this.buffer.byteLength < (this.value as TypedArray).byteLength + this.byteOffset
      ) {
        if (this.constant) {
          // Route legacy constant updater output through the same path used by constant accessors.
          const constantValue = this.value;
          this.value = null;
          this.setConstantValue(context, constantValue);
        } else {
          this.setData({
            value: this.value,
            constant: this.constant
          });
        }
        // Setting attribute.constant in updater is a legacy approach that interferes with allocation in the next cycle
        // Respect it here but reset after use
        this.constant = false;
      } else {
        for (const [startRow, endRow] of updateRanges) {
          const startOffset = Number.isFinite(startRow) ? this.getVertexOffset(startRow) : 0;
          const endOffset = Number.isFinite(endRow)
            ? this.getVertexOffset(endRow)
            : noAlloc || !Number.isFinite(numInstances)
              ? this.value.length
              : numInstances * this.size;

          super.updateSubBuffer({startOffset, endOffset});
        }
      }
      this._checkAttributeArray();
    } else {
      updated = false;
    }

    this.clearNeedsUpdate();
    this.setNeedsRedraw();

    return updated;
  }

  // Use generic value
  // Returns true if successful
  setConstantValue(context: any, value?: any): boolean {
    if (value === undefined || typeof value === 'function') {
      return false;
    }

    const transformedValue =
      this.settings.transform && context ? this.settings.transform.call(context, value) : value;
    let constant = transformedValue;
    switch (this.settings.semanticType) {
      case 'color':
        if (
          this.settings.normalizedColorInput &&
          Array.isArray(constant) &&
          value !== this.settings.defaultValue
        ) {
          packNormalizedColor(constant, COLOR_SCRATCH, 0, this.size);
          constant = COLOR_SCRATCH;
        }
        break;
      default:
        break;
    }
    this.setData({constant: true, value: constant});
    return true;
  }

  /** Updates storage, retaining raw constant bytes alongside shader-normalized values. */
  override setData(
    data: Parameters<DataColumn<AttributeOptions, AttributeInternalState>['setData']>[0]
  ): boolean {
    const wasConstant = this.isConstant;
    if (ArrayBuffer.isView(data) || data instanceof Buffer || !data.constant) {
      const hasChanged = super.setData(data);
      this.state.constantValue = null;
      this.state.layoutChanged ||= wasConstant && this.device.type === 'webgpu';
      return hasChanged;
    }
    const ArrayType = this.settings.defaultType;
    // DataColumn normalizes constants for shader consumption. Buffer grouping needs the original
    // vertex-format bytes so that interleaving preserves integer and normalized attribute formats.
    this.state.constantValue = this._normalizeValue(
      data.value,
      new ArrayType(this.size),
      0
    ) as TypedArray;
    const hasChanged = super.setData(data);
    if (this.device.type === 'webgpu') {
      let bufferValue = this.state.constantValue;
      if (
        this.doublePrecision &&
        (bufferValue instanceof Float32Array || bufferValue instanceof Float64Array)
      ) {
        // A zero low tuple must be present in the buffer on WebGPU even when the source is fp32.
        bufferValue = toDoublePrecisionArray(bufferValue, {size: this.size});
        this.setAccessor({
          ...this.getAccessor(),
          stride: this.size * 2 * Float32Array.BYTES_PER_ELEMENT
        });
      }
      let buffer = this._buffer;
      if (!buffer || buffer.byteLength < bufferValue.byteLength) {
        buffer = this._createBuffer(bufferValue.byteLength);
      }
      buffer.write(bufferValue);
      this.state.layoutChanged ||= !wasConstant;
      // `constant` is the legacy updater signal; persistent state lives in DataColumn.isConstant.
      this.constant = false;
    }

    if (hasChanged) {
      this.setNeedsRedraw();
    }
    this.clearNeedsUpdate();
    return hasChanged;
  }

  /** Returns one row in its vertex-buffer representation for WebGPU buffer grouping. */
  getConstantValue(): TypedArray | null {
    return this.isConstant ? this.state.constantValue : null;
  }

  // Use external buffer
  // Returns true if successful
  // eslint-disable-next-line max-statements
  setExternalBuffer(buffer?: TypedArray | Buffer | BinaryAttribute): boolean {
    const {state} = this;

    if (!buffer) {
      state.lastExternalBuffer = null;
      return false;
    }

    this.clearNeedsUpdate();

    if (state.lastExternalBuffer === buffer) {
      return true;
    }
    state.lastExternalBuffer = buffer;
    this.setNeedsRedraw();
    this.setData(buffer);
    return true;
  }

  // Binary value is a typed array packed from mapping the source data with the accessor
  // If the returned value from the accessor is the same as the attribute value, set it directly
  // Otherwise use the auto updater for transform/normalization
  setBinaryValue(
    buffer?: TypedArray | Buffer | BinaryAttribute | GPUVector,
    startIndices: NumericArray | null = null
  ): boolean {
    const {state, settings} = this;

    if (!buffer) {
      state.binaryValue = null;
      state.binaryAccessor = null;
      return false;
    }

    if (settings.noAlloc) {
      // Let the layer handle this
      return false;
    }

    if (buffer instanceof GPUVector) {
      assert(
        buffer.length >= this.numInstances,
        'GPUVector attribute is shorter than the draw count'
      );
    }

    // The source buffer can be unchanged while its projection/model matrix is invalidated.
    if (state.binaryValue === buffer && !(settings.transform && this.needsUpdate())) {
      this.clearNeedsUpdate();
      return true;
    }
    state.binaryValue = buffer;
    this.setNeedsRedraw();

    if (buffer instanceof GPUVector) {
      if (!buffer.format) throw new Error('GPUVector attributes require a format');
      const info = getGPUVectorFormatInfo(buffer.format);
      const type = info.type;
      if (type === 'float16') throw new Error('GPUVector float16 attributes are not supported');
      assert(
        !info.vertexList && !info.valueList,
        'GPUVector attributes require fixed-width values'
      );
      const chunk = getGPUVectorData(buffer);
      assert(chunk.buffer instanceof Buffer, 'GPUVector attributes require a concrete Buffer');
      buffer = {
        buffer: chunk.buffer as Buffer,
        type,
        size: info.components,
        offset: chunk.byteOffset,
        stride: chunk.byteStride
      };
    }

    const needsUpdate = settings.transform || startIndices !== this.startIndices;

    if (needsUpdate) {
      if (ArrayBuffer.isView(buffer)) {
        buffer = {value: buffer};
      }
      const binaryValue = buffer as BinaryAttribute;
      assert(ArrayBuffer.isView(binaryValue.value), `invalid ${settings.accessor}`);
      const needsNormalize = Boolean(binaryValue.size) && binaryValue.size !== this.size;

      state.binaryAccessor = getAccessorFromBuffer(binaryValue.value, {
        size: binaryValue.size || this.size,
        stride: binaryValue.stride,
        offset: binaryValue.offset,
        startIndices: startIndices as NumericArray,
        nested: needsNormalize
      });
      // Fall through to auto updater
      return false;
    }

    this.clearNeedsUpdate();
    this.setData(buffer);
    return true;
  }

  getVertexOffset(row: number): number {
    const {startIndices} = this;
    const vertexIndex = startIndices
      ? row < startIndices.length
        ? startIndices[row]
        : this.numInstances
      : row;
    return vertexIndex * this.size;
  }

  getValue(): Record<string, Buffer | TypedArray | null> {
    const shaderAttributeDefs = this.settings.shaderAttributes;
    const result = super.getValue();
    if (!shaderAttributeDefs) {
      return result;
    }
    for (const shaderAttributeName in shaderAttributeDefs) {
      Object.assign(
        result,
        super.getValue(shaderAttributeName, shaderAttributeDefs[shaderAttributeName])
      );
    }
    return result;
  }

  /**
   * Returns typed shader attributes without copying GPU storage. Vectors borrow this
   * attribute's buffers and must be reacquired after updates that replace storage.
   * Constants contain one raw, unnormalized row. Unallocated attributes are omitted.
   */
  getGPUVector(): Record<string, GPUVector | GPUConstant> {
    if (!this.isConstant && !this.getBuffer()) {
      return {};
    }
    const layout = this._getShaderBufferLayout();
    const values = this.getValue();
    const result: Record<string, GPUVector | GPUConstant> = {};
    let constantValue = this.getConstantValue();
    if (
      this.doublePrecision &&
      (constantValue instanceof Float32Array || constantValue instanceof Float64Array)
    ) {
      constantValue =
        this.device.type === 'webgpu'
          ? toDoublePrecisionArray(constantValue, {size: this.size})
          : new Float32Array([...this.value!, ...new Float32Array(this.size)]);
    }
    for (const definition of layout.attributes || []) {
      const name = definition.attribute;
      const value = values[name];
      const formatInfo = getGPUVectorFormatInfo(definition.format);
      if (this.isConstant && constantValue) {
        const ArrayType = getTypedArrayFromDataType(formatInfo.type);
        const offset = (definition.byteOffset || 0) / constantValue.BYTES_PER_ELEMENT;
        result[name] = new GPUConstant({
          format: definition.format,
          value: new ArrayType(constantValue.subarray(offset, offset + formatInfo.components))
        });
      } else if (value instanceof Buffer) {
        result[name] = new GPUVector({
          type: 'buffer',
          name,
          buffer: value,
          format: definition.format,
          length: this.numInstances,
          byteOffset: definition.byteOffset || 0,
          byteStride: layout.byteStride,
          ownsBuffer: false
        });
      } else if (value) {
        // Includes the synthetic fp64 low constant for float32 input on WebGL.
        result[name] = new GPUConstant({
          format: definition.format,
          value: new (getTypedArrayFromDataType(formatInfo.type))(value).subarray(
            0,
            formatInfo.components
          )
        });
      }
    }
    return result;
  }

  /** Generate WebGPU-style buffer layout descriptor from this attribute */
  getBufferLayout(
    /** A luma.gl Model-shaped object that supplies additional hint to attribute resolution */
    modelInfo?: {isInstanced?: boolean}
  ): BufferLayout {
    this.state.layoutChanged = false;
    return this._getShaderBufferLayout(modelInfo);
  }

  private _getShaderBufferLayout(modelInfo?: {isInstanced?: boolean}): BufferLayout {
    const shaderAttributeDefs = this.settings.shaderAttributes;
    const result: BufferLayout = super._getBufferLayout();
    const {stepMode} = this.settings;
    if (stepMode === 'dynamic') {
      // If model info is provided, use isInstanced flag to determine step mode
      // If no model info is provided, assume it's an instanced model (most common use case)
      result.stepMode = modelInfo ? (modelInfo.isInstanced ? 'instance' : 'vertex') : 'instance';
    } else {
      result.stepMode = stepMode ?? 'vertex';
    }

    if (!shaderAttributeDefs) {
      return result;
    }

    for (const shaderAttributeName in shaderAttributeDefs) {
      const map = super._getBufferLayout(
        shaderAttributeName,
        shaderAttributeDefs[shaderAttributeName]
      );
      // @ts-ignore
      result.attributes.push(...map.attributes);
    }
    return result;
  }

  /* eslint-disable max-depth, max-statements */
  private _autoUpdater(
    attribute: Attribute,
    {
      data,
      startRow,
      endRow,
      props,
      numInstances
    }: {
      data: any;
      startRow: number;
      endRow: number;
      props: any;
      numInstances: number;
    }
  ): void {
    const {settings, state, value, size, startIndices} = attribute;

    const {accessor, transform} = settings;
    const normalizeColor =
      settings.semanticType === 'color' && settings.normalizedColorInput && !state.binaryAccessor;
    const accessorFunc: Accessor<any, any> =
      state.binaryAccessor ||
      // @ts-ignore
      (typeof accessor === 'function' ? accessor : props[accessor]);
    assert(typeof accessorFunc === 'function', `accessor "${accessor}" is not a function`);

    let i = attribute.getVertexOffset(startRow);
    const {iterable, objectInfo} = createIterable(data, startRow, endRow);
    for (const object of iterable) {
      objectInfo.index++;

      let objectValue = accessorFunc(object, objectInfo);
      if (transform) {
        // transform callbacks could be bound to a particular layer instance.
        // always point `this` to the current layer.
        objectValue = transform.call(this, objectValue);
      }

      /** Whether this row contains plain-array colors to pack. */
      const normalizeRow = normalizeColor && Array.isArray(objectValue);
      /** Whether the row starts with a typed per-vertex color. */
      const nestedColor = startIndices && ArrayBuffer.isView(objectValue?.[0]);
      /** Whether the row contains flat per-vertex color channels. */
      const flatColors = normalizeRow && startIndices && objectValue.length > 4;
      if (
        normalizeRow &&
        !nestedColor &&
        !flatColors &&
        (!startIndices || !Array.isArray(objectValue[0]))
      ) {
        COLOR_SCRATCH.length = size;
        packNormalizedColor(objectValue, COLOR_SCRATCH, 0, size);
        objectValue = COLOR_SCRATCH;
      }

      if (startIndices) {
        const numVertices =
          (objectInfo.index < startIndices.length - 1
            ? startIndices[objectInfo.index + 1]
            : numInstances) - startIndices[objectInfo.index];
        if (objectValue && (Array.isArray(objectValue[0]) || nestedColor)) {
          let startIndex = i;
          for (const item of objectValue) {
            if (normalizeRow && Array.isArray(item)) {
              packNormalizedColor(item, value as TypedArray, startIndex, size);
            } else {
              attribute._normalizeValue(item, value as TypedArray, startIndex);
            }
            startIndex += size;
          }
        } else if (flatColors) {
          for (let offset = 0; offset < objectValue.length; offset += size) {
            packNormalizedColor(objectValue, value as TypedArray, i + offset, size, offset);
          }
        } else if (
          objectValue &&
          objectValue.length > size &&
          !(size === 3 && objectValue instanceof Uint8ClampedArray && objectValue.length === 4)
        ) {
          (value as TypedArray).set(objectValue, i);
        } else {
          attribute._normalizeValue(objectValue, objectInfo.target, 0);
          fillArray({
            target: value,
            source: objectInfo.target,
            start: i,
            count: numVertices
          });
        }
        i += numVertices * size;
      } else {
        attribute._normalizeValue(objectValue, value as TypedArray, i);
        i += size;
      }
    }
  }
  /* eslint-enable max-depth, max-statements */

  // Validate deck.gl level fields
  private _validateAttributeUpdaters() {
    const {settings} = this;

    // Check that 'update' is a valid function
    const hasUpdater = settings.noAlloc || typeof settings.update === 'function';
    if (!hasUpdater) {
      throw new Error(`Attribute ${this.id} missing update or accessor`);
    }
  }

  // check that the first few elements of the attribute are reasonable
  /* eslint-disable no-fallthrough */
  private _checkAttributeArray() {
    const {value} = this;
    const limit = Math.min(4, this.size);
    if (value && value.length >= limit) {
      let valid = true;
      switch (limit) {
        case 4:
          valid = valid && Number.isFinite(value[3]);
        case 3:
          valid = valid && Number.isFinite(value[2]);
        case 2:
          valid = valid && Number.isFinite(value[1]);
        case 1:
          valid = valid && Number.isFinite(value[0]);
          break;
        default:
          valid = false;
      }

      if (!valid) {
        throw new Error(`Illegal attribute generated for ${this.id}`);
      }
    }
  }
  /* eslint-enable no-fallthrough */
}
