// View and Projection Matrix calculations for mapbox-js style
// map view properties
import Viewport, {
  type ViewportOptions,
  type DistanceScales,
  type ProjectPositionOptions
} from './viewport';
import {PROJECTION_MODE} from '../shaderlib/project/constants';
import {OSM_TILE_CRS, getMercatorScales} from './web-mercator-util';

import {
  pixelsToWorld,
  lngLatToWorld,
  worldToLngLat,
  getViewMatrix,
  addMetersToLngLat,
  unitsPerMeter,
  getProjectionParameters,
  altitudeToFovy,
  fovyToAltitude,
  fitBounds,
  getBounds
} from '@math.gl/geospatial/web-mercator';
import {Padding} from './viewport';

import {Matrix4, Vector3, clamp} from '@math.gl/core/matrix';
import {vec2} from '@math.gl/core/matrix';

export type WebMercatorViewportOptions = {
  /** Subdivision intervals around the earth for nonlinear source CRS conversions. Default 0 disables subdivision. */
  resolution?: number;
  /** Name of the viewport */
  id?: string;
  /** Left offset from the canvas edge, in pixels */
  x?: number;
  /** Top offset from the canvas edge, in pixels */
  y?: number;
  /** Viewport width in pixels */
  width?: number;
  /** Viewport height in pixels */
  height?: number;
  /** Longitude in degrees */
  longitude?: number;
  /** Latitude in degrees */
  latitude?: number;
  /** Tilt of the camera in degrees */
  pitch?: number;
  /** Heading of the camera in degrees */
  bearing?: number;
  /** Camera altitude relative to the viewport height, legacy property used to control the FOV. Default `1.5` */
  altitude?: number;
  /** Camera fovy in degrees. If provided, overrides `altitude` */
  fovy?: number;
  /** Viewport center in world space. If geospatial, refers to meter offsets from lng, lat, elevation */
  position?: number[];
  /** Zoom level */
  zoom?: number;
  /** Padding around the viewport, in pixels. */
  padding?: Padding | null;
  /** Model matrix of viewport center */
  modelMatrix?: number[] | null;
  /** Custom projection matrix */
  projectionMatrix?: number[];
  /** Use orthographic projection */
  orthographic?: boolean;
  /** Scaler for the near plane, 1 unit equals to the height of the viewport. Default `0.1` */
  nearZMultiplier?: number;
  /** Scaler for the far plane, 1 unit equals to the distance from the camera to the edge of the screen. Default `1.01` */
  farZMultiplier?: number;
  /** Optionally override the near plane position. `nearZMultiplier` is ignored if `nearZ` is supplied. */
  nearZ?: number;
  /** Optionally override the far plane position. `farZMultiplier` is ignored if `farZ` is supplied. */
  farZ?: number;
  /** Render multiple copies of the world */
  repeat?: boolean;
  /** Internal use */
  worldOffset?: number;
  /** @deprecated Revert to approximated meter size calculation prior to v8.5 */
  legacyMeterSizes?: boolean;
};

type MercatorCameraOptions = ViewportOptions &
  Pick<
    WebMercatorViewportOptions,
    'longitude' | 'latitude' | 'pitch' | 'bearing' | 'altitude' | 'repeat' | 'legacyMeterSizes'
  >;

/**
 * Manages transformations to/from WGS84 coordinates using the Web Mercator Projection.
 */
export default class WebMercatorViewport extends Viewport {
  static displayName = 'WebMercatorViewport';

  longitude: number;
  latitude: number;
  pitch: number;
  bearing: number;
  altitude: number;
  fovy: number;
  orthographic: boolean;

  /** Each sub viewport renders one copy of the world if repeat:true. The list is generated and cached on first request. */
  private _subViewports: WebMercatorViewport[] | null;
  /** @deprecated Revert to approximated meter size calculation prior to v8.5 */
  private _pseudoMeters: boolean;

  constructor(opts: WebMercatorViewportOptions = {}) {
    const options = WebMercatorViewport._getViewportOptions(opts);
    super(options);
    this.latitude = options.latitude ?? 0;
    this.longitude = options.longitude ?? 0;
    this.zoom = options.zoom ?? 0;
    this.pitch = options.pitch ?? 0;
    this.bearing = options.bearing ?? 0;
    this.altitude = options.altitude ?? 1.5;
    this.fovy = options.fovy ?? 75;
    this.orthographic = options.orthographic ?? false;
    this._subViewports = options.repeat ? [] : null;
    this._pseudoMeters = options.legacyMeterSizes ?? false;
    Object.freeze(this);
  }

  /** Prepare map-camera parameters before initializing the base viewport. */
  /* eslint-disable complexity, max-statements */
  private static _getViewportOptions(opts: WebMercatorViewportOptions): MercatorCameraOptions {
    const {
      latitude = 0,
      longitude = 0,
      zoom = 0,
      pitch = 0,
      bearing = 0,
      nearZMultiplier = 0.1,
      farZMultiplier = 1.01,
      nearZ,
      farZ,
      orthographic = false,
      projectionMatrix,

      worldOffset = 0,
      position,
      padding
    } = opts;

    let {width, height, altitude = 1.5} = opts;
    const scale = Math.pow(2, zoom);

    // Silently allow apps to send in 0,0 to facilitate isomorphic render etc
    width = width || 1;
    height = height || 1;

    let fovy;
    let projectionParameters: any = null;
    if (projectionMatrix) {
      altitude = projectionMatrix[5] / 2;
      fovy = altitudeToFovy(altitude);
    } else {
      if (opts.fovy) {
        fovy = opts.fovy;
        altitude = fovyToAltitude(fovy);
      } else {
        fovy = altitudeToFovy(altitude);
      }

      let offset: [number, number] | undefined;
      if (padding) {
        const {top = 0, bottom = 0} = padding;
        offset = [0, clamp((top + height - bottom) / 2, 0, height) - height / 2];
      }

      projectionParameters = getProjectionParameters({
        width,
        height,
        scale,
        center: position && [0, 0, position[2] * unitsPerMeter(latitude)],
        offset,
        pitch,
        fovy,
        nearZMultiplier,
        farZMultiplier
      });

      if (Number.isFinite(nearZ)) {
        projectionParameters.near = nearZ;
      }
      if (Number.isFinite(farZ)) {
        projectionParameters.far = farZ;
      }
    }

    // The uncentered matrix allows us two move the center addition to the
    // shader (cheap) which gives a coordinate system that has its center in
    // the layer's center position. This makes rotations and other modelMatrx
    // transforms much more useful.
    let viewMatrixUncentered = getViewMatrix({
      height,
      pitch,
      bearing,
      scale,
      altitude
    });

    if (worldOffset) {
      const viewOffset = new Matrix4().translate([512 * worldOffset, 0, 0]);
      viewMatrixUncentered = viewOffset.multiplyLeft(viewMatrixUncentered);
    }

    // Empty aggregation grids can supply non-finite anchors. Preserve the legacy
    // local-coordinate fallback rather than sampling Mercator scales at NaN.
    const geospatial = Number.isFinite(longitude) && Number.isFinite(latitude);
    return {
      ...opts,
      crs: geospatial ? OSM_TILE_CRS : undefined,
      distanceScales: geospatial ? getMercatorScales(longitude, latitude) : undefined,
      // x, y,
      width,
      height,

      // view matrix
      viewMatrix: viewMatrixUncentered,
      longitude,
      latitude,
      zoom,

      // projection matrix parameters
      ...projectionParameters,
      fovy,
      focalDistance: altitude,
      altitude,
      orthographic
    };
  }
  /* eslint-enable complexity, max-statements */

  protected _getCenter(options: MercatorCameraOptions, position: number[]): number[] {
    if (!this.crs) return super._getCenter(options, position);
    return new Vector3(position)
      .scale(this.distanceScales.unitsPerMeter)
      .add(this.projectPosition([options.longitude ?? 0, options.latitude ?? 0, 0]));
  }

  get projectionMode(): number {
    return this.crs
      ? this.zoom < 12
        ? PROJECTION_MODE.WEB_MERCATOR
        : PROJECTION_MODE.WEB_MERCATOR_AUTO_OFFSET
      : PROJECTION_MODE.IDENTITY;
  }

  projectFlat(position: number[]): [number, number] {
    if (!this.crs) return position as [number, number];
    const projected = lngLatToWorld(position);
    // Match the shader's latitude clamp while allowing continuous repeated worlds.
    projected[1] = clamp(projected[1], -318, 830);
    return projected;
  }

  unprojectFlat(position: number[]): [number, number] {
    return this.crs ? worldToLngLat(position) : (position as [number, number]);
  }

  /** Mercator scales at a WGS84 longitude/latitude anchor. */
  getDistanceScales(coordinateOrigin?: number[]): DistanceScales {
    return coordinateOrigin && this.crs
      ? getMercatorScales(coordinateOrigin[0], coordinateOrigin[1], true)
      : this.distanceScales;
  }

  get subViewports(): WebMercatorViewport[] | null {
    if (this._subViewports && !this._subViewports.length) {
      // Cache sub viewports so that we only calculate them once
      const bounds = this.getBounds();

      const minOffset = Math.floor((bounds[0] + 180) / 360);
      const maxOffset = Math.ceil((bounds[2] - 180) / 360);

      for (let x = minOffset; x <= maxOffset; x++) {
        const offsetViewport = x
          ? new WebMercatorViewport({
              ...this,
              worldOffset: x
            })
          : this;
        this._subViewports.push(offsetViewport);
      }
    }
    return this._subViewports;
  }

  /** Returns whether two Web Mercator viewports use the same projection settings. */
  equals(viewport: Viewport): boolean {
    return (
      viewport instanceof WebMercatorViewport &&
      viewport._pseudoMeters === this._pseudoMeters &&
      super.equals(viewport)
    );
  }

  projectPosition(xyz: number[], options: ProjectPositionOptions = {}): [number, number, number] {
    if (options.sourceCrs) return this._projectPositionFromCRS(xyz, options.sourceCrs);
    if (this._pseudoMeters) {
      const [x, y] = this.projectFlat(xyz);
      return [x, y, (xyz[2] || 0) * this.distanceScales.unitsPerWorldUnit[2]];
    }
    const [X, Y] = this.projectFlat(xyz);
    const Z = (xyz[2] || 0) * unitsPerMeter(xyz[1]);
    return [X, Y, Z];
  }

  unprojectPosition(xyz: number[]): [number, number, number] {
    if (this._pseudoMeters) {
      const [x, y] = this.unprojectFlat(xyz);
      return [x, y, (xyz[2] || 0) / this.distanceScales.unitsPerWorldUnit[2]];
    }
    const [X, Y] = this.unprojectFlat(xyz);
    const Z = (xyz[2] || 0) / unitsPerMeter(Y);
    return [X, Y, Z];
  }

  /**
   * Add a meter delta to a base lnglat coordinate, returning a new lnglat array
   *
   * Note: Uses simple linear approximation around the viewport center
   * Error increases with size of offset (roughly 1% per 100km)
   *
   * @param {[Number,Number]|[Number,Number,Number]) lngLatZ - base coordinate
   * @param {[Number,Number]|[Number,Number,Number]) xyz - array of meter deltas
   * @return {[Number,Number]|[Number,Number,Number]) array of [lng,lat,z] deltas
   */
  addMetersToLngLat(lngLatZ: number[], xyz: number[]): number[] {
    return addMetersToLngLat(lngLatZ, xyz);
  }

  panByPosition(
    coords: number[],
    pixel: number[],
    startPixel?: number[]
  ): WebMercatorViewportOptions {
    const fromLocation = pixelsToWorld(pixel, this.pixelUnprojectionMatrix);
    const toLocation = this.projectFlat(coords);

    const translate = vec2.add([], toLocation, vec2.negate([], fromLocation));
    const newCenter = vec2.add([], this.center, translate);

    const [longitude, latitude] = this.unprojectFlat(newCenter);
    return {longitude, latitude};
  }

  /**
   * Returns a new longitude and latitude that keeps a 3D world coordinate at a given screen pixel
   * This version handles the z-component (altitude) properly for cameras positioned above ground
   */
  panByPosition3D(coords: number[], pixel: number[]): WebMercatorViewportOptions {
    const targetZ = coords[2] || 0;
    const deltaLngLat = vec2.sub([], coords, this.unproject(pixel, {targetZ}));
    return {longitude: this.longitude + deltaLngLat[0], latitude: this.latitude + deltaLngLat[1]};
  }

  getBounds(options: {z?: number} = {}): [number, number, number, number] {
    // math.gl types this helper with its own viewport class; deck supplies the fields it uses.
    // @ts-ignore
    const corners = getBounds(this, options.z || 0);

    return [
      Math.min(corners[0][0], corners[1][0], corners[2][0], corners[3][0]),
      Math.min(corners[0][1], corners[1][1], corners[2][1], corners[3][1]),
      Math.max(corners[0][0], corners[1][0], corners[2][0], corners[3][0]),
      Math.max(corners[0][1], corners[1][1], corners[2][1], corners[3][1])
    ];
  }

  /**
   * Returns a new viewport that fit around the given rectangle.
   * Only supports non-perspective mode.
   */
  fitBounds(
    /** [[lon, lat], [lon, lat]] */
    bounds: [[number, number], [number, number]],
    options: {
      /** If not supplied, will use the current width of the viewport (default `1`) */
      width?: number;
      /** If not supplied, will use the current height of the viewport (default `1`) */
      height?: number;
      /** In degrees, 0.01 would be about 1000 meters */
      minExtent?: number;
      /** Max zoom level */
      maxZoom?: number;
      /** Extra padding in pixels */
      padding?: number | Required<Padding>;
      /** Center shift in pixels */
      offset?: number[];
    } = {}
  ) {
    const {width, height} = this;
    const {longitude, latitude, zoom} = fitBounds({width, height, bounds, ...options});
    return new WebMercatorViewport({width, height, longitude, latitude, zoom});
  }
}
